"""מנוע שיחה של גבי — עונה לתשובות חייבים, מציע הסדר, מסלים לבעל העסק.

טהור לגמרי: בלי DB, בלי רשת, בלי שעון (היום מוזרק ב-`Context.today`). לכן כל
החלטה ניתנת לשחזור ונבדקת ב-eval (`evals/`).

עקרונות (לפי MVP-SPEC §2.3 וההכרעה "בעל העסק מאשר כל הודעה"):
  1. ההחלטה (עצירה/השהיה/הסלמה) נגזרת מ*כל* הכוונות שזוהו, לא רק מהעיקרית.
     "לא הזמנתי כלום, תפסיקו לשלוח" ⇒ גם הסרה לצמיתות וגם הסלמה דחופה.
  2. התשובה היא תמיד *טיוטה*. היא יוצאת אוטומטית רק במצב `safe_auto` ורק לכוונות
     מידע בטוחות. ברירת המחדל = הכול לאישור בעל העסק.
  3. מעקות על התשובה (`check_reply`): בלי איום, בלי ריבית/קנס, בלי הנחה שלא אושרה,
     בלי "התשלום התקבל", בלי לחשוף סכום למי שאמר "טעות במספר", אורך SMS סביר.
     טיוטת LLM שנכשלת במעקה ⇒ חוזרים לנוסח הקבוע.
  4. מה שלא בטוח ⇒ בעל העסק. LLM (שלב 2) רק מסווג טקסט שהכללים לא זיהו,
     בחירה מתוך רשימה סגורה, ולא יכול לבטל הסלמה.
  5. ערוצים: SMS ומייל בלבד (לא WhatsApp — מדיניות Meta). המנוע לא שולח כלום.
"""
from __future__ import annotations

import calendar
import logging
import re
from collections.abc import Callable
from dataclasses import dataclass, field, replace
from datetime import date, timedelta
from enum import Enum
from functools import cache
from typing import Protocol

from . import compliance
from .plans import Installment, _add_months
from .templates import fmt_amount

log = logging.getLogger(__name__)


# ═══════════════════════════ סוגים ═══════════════════════════
class Intent(str, Enum):
    DISTRESS = "distress"            # מצוקה רגשית קשה — רק בן אדם
    OPT_OUT = "opt_out"              # הסר / תפסיקו לשלוח
    WRONG_PERSON = "wrong_person"    # טעות במספר — לא החייב
    LEGAL = "legal"                  # עו"ד / תביעה / משטרה מצד הלקוח
    DISPUTE = "dispute"              # מחלוקת על החוב
    PAID_CLAIM = "paid_claim"        # שילמתי (מלא או חלקי)
    CANT_PAY = "cant_pay"            # אין כסף / קושי / מילואים / מחלה
    PLAN_REQUEST = "plan_request"    # רוצה תשלומים / פריסה
    PLAN_ACCEPT = "plan_accept"      # מאשר הצעה שנשלחה
    PLAN_REJECT = "plan_reject"      # דוחה הצעה שנשלחה
    PROMISE = "promise"              # אשלם ב... / אפשר לדחות ל...
    COPY_REQUEST = "copy_request"    # שלחו חשבונית / פירוט
    HOW_TO_PAY = "how_to_pay"        # איך משלמים / קישור
    CALLBACK = "callback"            # תתקשרו אליי
    WHO_IS_THIS = "who_is_this"      # מי זה? על מה?
    ABUSIVE = "abusive"              # קללות
    THANKS = "thanks"                # תודה / קיבלתי
    MINOR = "minor"                  # קטין עונה (ר-6) — לא מנהלים איתו שיחה על חוב
    UNKNOWN = "unknown"


class Escalation(str, Enum):
    NONE = "none"
    NORMAL = "normal"
    URGENT = "urgent"


class Stop(str, Enum):
    NONE = "none"            # התזכורות ממשיכות
    PAUSE = "pause"          # השהיה (עד תאריך / עד הכרעת בעלים)
    PERMANENT = "permanent"  # לעולם לא עוד תזכורות אוטומטיות לאיש קשר הזה


class State(str, Enum):
    IDLE = "idle"
    AWAITING_PLAN_REPLY = "awaiting_plan_reply"      # נשלחה הצעת פריסה
    PLAN_PENDING_OWNER = "plan_pending_owner"        # הלקוח אישר, בעל העסק עוד לא
    AWAITING_DATE = "awaiting_date"                  # שאלנו "עד מתי?"
    PROMISED = "promised"                            # יש מועד מוסכם
    AWAITING_OWNER = "awaiting_owner"                # הועבר לבעל העסק
    OPTED_OUT = "opted_out"


@dataclass(frozen=True)
class OpenInvoice:
    number: str
    amount_agorot: int
    currency: str = "ILS"
    due: date | None = None


@dataclass(frozen=True)
class OwnerPolicy:
    """גבולות שבעל העסק קבע. המנוע לעולם לא מציע מעבר להם."""
    max_installments: int = 6
    min_installment_agorot: int = 100_00
    default_installments: int = 3
    first_installment_in_days: int = 7
    auto_offer_plan: bool = True      # מותר לנסח הצעת פריסה בתוך הגבולות (עדיין טיוטה)
    max_defer_days: int = 14          # הבטחת תשלום עד X ימים ⇒ מקבלים ומשהים לבד
    approval_mode: str = "all"        # "all" | "safe_auto"
    max_bot_turns: int = 4            # אחרי כך — רק בעל העסק עונה


@dataclass(frozen=True)
class Context:
    today: date
    business: str
    customer_name: str = ""
    invoices: tuple[OpenInvoice, ...] = ()
    payment_link: str = ""
    channel: str = "sms"              # "sms" | "email"
    state: State = State.IDLE
    offered_plan: tuple[Installment, ...] = ()
    bot_turns: int = 0                # כמה תשובות שלנו כבר היו בשיחה הזו
    policy: OwnerPolicy = field(default_factory=OwnerPolicy)
    manual_old: bool = False          # ר-7: יש חשבונית פתוחה מעל 3 שנים ⇒ אין הצעת פריסה אוטומטית
    footer_len: int = 0               # אורך שורת ההסרה שתתווסף ב-SMS (נשמר מקום בתקציב 268)
    plan_approved: bool = False       # מנהל 265: בעל העסק כבר אישר ושלח את ההסדר (plans.status='approved')

    def fits_sms(self, body: str) -> bool:
        """הגוף (לפני שם העסק) + שם העסק + שורת ההסרה ≤ תקרת התשובה ב-SMS."""
        return self.channel != "sms" or \
            len(frame(body, self)) + self.footer_len <= compliance.SMS_REPLY_MAX

    @property
    def total_agorot(self) -> int:
        return sum(i.amount_agorot for i in self.invoices)

    @property
    def currency(self) -> str:
        return self.invoices[0].currency if self.invoices else "ILS"

    @property
    def mixed_currency(self) -> bool:
        """חשבוניות פתוחות במטבעות שונים ⇒ אין סה״כ אחד (שקל+דולר לא מחברים), ולכן גם אין הצעת
        פריסה אוטומטית — `service.open_debt` מחזיר 0 ולא רושם הסדר. כרטיס לבעל העסק במקום."""
        return len({i.currency for i in self.invoices}) > 1

    def total_text(self) -> str:
        """הסכום לתצוגה. מטבעות שונים ⇒ סכום לכל מטבע («₪1,000 + $200»), לא חיבור."""
        if not self.mixed_currency:
            return fmt_amount(self.total_agorot, self.currency) if self.invoices else ""
        by: dict[str, int] = {}
        for i in self.invoices:
            by[i.currency] = by.get(i.currency, 0) + i.amount_agorot
        return " + ".join(fmt_amount(v, c) for c, v in by.items())

    @property
    def first_name(self) -> str:
        return (self.customer_name or "").split()[0] if self.customer_name.strip() else ""


@dataclass(frozen=True)
class Decision:
    intent: Intent
    secondary: tuple[Intent, ...]
    reply: str | None                 # טיוטת תשובה; None ⇒ לא עונים
    auto_send: bool                   # מותר לשלוח בלי אישור? (ברירת מחדל: לא)
    escalate: Escalation
    stop: Stop
    pause_until: date | None          # כש-stop=PAUSE: עד מתי (None ⇒ עד הכרעת בעלים)
    next_state: State
    plan: tuple[Installment, ...] = ()
    promise_date: date | None = None
    paid_agorot: int | None = None    # סכום שהלקוח טוען ששילם
    owner_summary: str = ""
    owner_actions: tuple[str, ...] = ()
    tags: tuple[str, ...] = ()
    confidence: str = "rules"         # "rules" | "llm" | "none"
    guardrail_issues: tuple[str, ...] = ()

    @property
    def all_intents(self) -> tuple[Intent, ...]:
        return (self.intent, *self.secondary)


class LLMClassifier(Protocol):  # שלב 2 — Claude Haiku עם פלט enum בלבד
    def classify(self, text: str) -> str: ...


class LLMDrafter(Protocol):  # שלב 2 — מנסח מחדש טיוטה; תמיד עובר מעקה ואישור
    def draft(self, intent: Intent, base_reply: str, ctx: Context) -> str: ...


# ═══════════════════════════ נרמול ═══════════════════════════
_NIKUD = re.compile("[\u0591-\u05C7]")
_QUOTES = str.maketrans({"״": '"', "”": '"', "“": '"', "׳": "'", "’": "'", "‘": "'",
                         "`": "'", "–": "-", "—": "-", "\u200f": "", "\u200e": ""})
_FINALS = str.maketrans("ךםןףץ", "כמנפצ")


# מנהל 270 («הבא» AI מ-269): סכום חודשי במילים — «can we do two hundred a month?» ⇒ היה «ביקש/ה 2 תשלומים» (two נקרא
# מספר תשלומים); «I can pay two hundred a month» / «אולי מאתיים בחודש?» ⇒ «לא ברור»; «אשלם שלוש מאות לחודש» ⇒ הבטחה בלי תאריך.
# ממירים לספרות **רק** רצף מילות-מספר שצמוד לעוגן חודשי (מטבע אופציונלי), ורק ≥100 או עם מטבע מפורש
# («עשרים לחודש» = כנראה יום בחודש; «two payments a month» לא נוגע — payments מפריד).
_EN_ONES = {"a": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9,
            "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14, "fifteen": 15, "sixteen": 16,
            "seventeen": 17, "eighteen": 18, "nineteen": 19}
_EN_TENS = {"twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90}
_EN_NUMTOK = "|".join(sorted([*_EN_ONES, *_EN_TENS, "hundred", "thousand"], key=len, reverse=True))
_EN_AMT_WORDS_RX = re.compile(
    r"\b((?:" + _EN_NUMTOK + r")(?:(?:\s+|-|\s+and\s+)(?:" + _EN_NUMTOK + r"))*)"
    r"(?=\s*(?P<cur>shekels?|nis|ils|dollars?|bucks)?\s*(?:(?:a|per|each|every)\s+month\b|/\s*(?:month|mo)\b|monthly\b))")
_HE_ONES = {"אחת": 1, "אחד": 1, "שתיים": 2, "שניים": 2, "שתי": 2, "שני": 2, "שלוש": 3, "שלושה": 3, "ארבע": 4,
            "ארבעה": 4, "חמש": 5, "חמישה": 5, "שש": 6, "שישה": 6, "שבע": 7, "שבעה": 7, "שמונה": 8, "תשע": 9, "תשעה": 9,
            # critic סבב 130: צורת סמיכות («שלושת אלפים») — לפני כן «אלפים» לבד = 1000 ⇒ 2×600 במקום «3000 לחודש»
            "שלושת": 3, "ארבעת": 4, "חמשת": 5, "ששת": 6, "שבעת": 7, "שמונת": 8, "תשעת": 9}
_HE_TENS = {"עשר": 10, "עשרה": 10, "עשרים": 20, "שלושים": 30, "ארבעים": 40, "חמישים": 50, "שישים": 60, "שבעים": 70,
            "שמונים": 80, "תשעים": 90}
_HE_BIG = {"מאה": 100, "מאתיים": 200, "מאות": 100, "אלף": 1000, "אלפיים": 2000, "אלפים": 1000}
_HE_NUM = {k.translate(_FINALS): v for d in (_HE_ONES, _HE_TENS, _HE_BIG) for k, v in d.items()}
_HE_NUMTOK = "|".join(sorted(_HE_NUM, key=len, reverse=True))
_HE_AMT_WORDS_RX = re.compile(
    r"(?<![\w])((?:" + _HE_NUMTOK + r")(?:\s+ו?(?:" + _HE_NUMTOK + r"))*)"
    r"(?=\s*(?P<cur>ש\"ח|שח|שקל\w*)?\s*(?:(?:ב)?כל חודש|לחודש|בחודש(?! ה))(?![\w]))")


def _words_value(tokens: list[int | str]) -> int | None:
    """[2, 'hundred', 50] ⇒ 250 · [15, 'hundred'] ⇒ 1500 · [1, 'thousand', 2, 'hundred'] ⇒ 1200."""
    total = cur = 0
    for tk in tokens:
        if tk == "hundred":
            cur = (cur or 1) * 100
        elif tk == "thousand":
            total += (cur or 1) * 1000
            cur = 0
        elif isinstance(tk, int):
            cur += tk
        else:
            return None
    v = total + cur
    return v or None


def _en_amount_tokens(phrase: str) -> list[int | str]:
    out: list[int | str] = []
    for w in re.split(r"[\s-]+", phrase):
        if w in ("and", ""):
            continue
        out.append(w if w in ("hundred", "thousand") else _EN_ONES.get(w) or _EN_TENS[w])
    return out


def _he_amount_tokens(phrase: str) -> list[int | str]:
    out: list[int | str] = []
    for w in phrase.split():
        w = w[1:] if w.startswith("ו") and w[1:] in _HE_NUM else w
        if w == "מאות":
            out.append("hundred")
        elif w in ("אלפ", "אלפימ"):
            out.append("thousand")
        elif w == "אלפיימ":
            out += [2, "thousand"]
        else:
            out.append(_HE_NUM[w])
    return out


def _amount_words_to_digits(t: str) -> str:
    def sub(rx: re.Pattern[str], tok: Callable[[str], list[int | str]]) -> str:
        def rep(m: re.Match[str]) -> str:
            try:
                v = _words_value(tok(m.group(1)))
            except KeyError:
                return m.group(0)
            if v is None or (v < 100 and not m.group("cur")):
                return m.group(0)
            return str(v)
        return rx.sub(rep, t)
    if any(c.isascii() and c.isalpha() for c in t):
        t = sub(_EN_AMT_WORDS_RX, _en_amount_tokens)
    return sub(_HE_AMT_WORDS_RX, _he_amount_tokens)


def normalize(text: str) -> str:
    t = _NIKUD.sub("", text or "").translate(_QUOTES).lower()
    t = t.replace("''", '"').translate(_FINALS)  # אותיות סופיות ⇒ רגילות (גם בתבניות)
    # "תודההההה" ⇒ "תודהה". מנהל 270: לא ספרות — «שילמתי 1000» נקרא 100 ₪, «אשלם 1000 לחודש» ⇒ ₪100 (50 תשלומים)
    t = re.sub(r"([^\d])\1{2,}", r"\1\1", t)
    t = re.sub(r"\s+", " ", t)
    return _amount_words_to_digits(t.strip())


@cache
def _c(pat: str) -> re.Pattern[str]:
    """קומפילציה של תבנית שרצה על טקסט מנורמל: גם בה אותיות סופיות ⇒ רגילות."""
    return re.compile(pat.translate(_FINALS))


def _s(pat: str, t: str) -> re.Match[str] | None:
    return _c(pat).search(t)


def _fm(pat: str, t: str) -> re.Match[str] | None:
    return _c(pat).fullmatch(t)


def _m(pat: str, t: str) -> re.Match[str] | None:
    return _c(pat).match(t)


# תחיליות עבריות נפוצות לפני מילה: ו/ש/כש/ה/ב/ל/מ וצירופים
_P = r"(?<![\w])(?:ו?(?:כש|ש|ה|ב|ל|מ){0,2})?"
_E = r"(?![\w])"


def _w(*words: str) -> str:
    """מילה שלמה עם תחיליות מותרות."""
    return _P + "(?:" + "|".join(words) + ")" + _E


def _ws(*stems: str) -> str:
    """שורש + כל סיומת (למשל שילמ ⇒ שילמתי/שילמנו/שילמה)."""
    return _P + "(?:" + "|".join(stems) + r")\w*"


_NEG_BEFORE = _c(r"(?:(?<![\w])(?:לא|טרם|עוד לא|עדיין לא|אף פעם לא|לא ממש|בלי ש|מבלי ש|אל|אין צורך|"
                 r"לא (?:צריך|צריכה|צריכים|ביקשתי|ביקשנו|מבקש|מבקשת|רוצה|התכוונתי)(?: ל)?|"
                         r"לא\s+\w+\s+ש)\s*$)")


def _hits(pattern: re.Pattern[str], t: str, *, negatable: bool = False) -> bool:
    for m in pattern.finditer(t):
        if negatable and _NEG_BEFORE.search(t[max(0, m.start() - 22):m.start()]):
            continue
        return True
    return False


# מנהל 250 (סריקת גבולות מילה): חלק שמתחיל באות עברית יכול היה להתחיל באמצע מילה —
# «די לשלוח» בתוך «כדי לשלוח» ⇒ הסרה לצמיתות של לקוח ששאל איך לשלם; «נזק» בתוך «טרנזקציה» ⇒ מחלוקת;
# «חולה» בתוך «כחולה» ⇒ השהיה. השער: תחילת ההתאמה = תחילת מילה, או אחרי תחילית עברית תקנית בלבד
# (ו/ש/כש/ה/ב/ל/מ, כמו _P). lookbehind בלבד ⇒ נקודת ההתחלה לא זזה ובדיקת השלילה (_NEG_BEFORE) לא משתנה.
_HEB_START = re.compile(r"^(?:\(\?:|\(|\^)*[\u05D0-\u05EA]")


def _lead_variants() -> list[str]:
    units = ("כש", "ש", "ה", "ב", "ל", "מ")
    out = {""}
    for a in ("", "ו"):
        out.add(a)
        for u1 in units:
            out.add(a + u1)
            for u2 in units:
                out.add(a + u1 + u2)
    return sorted(v.translate(_FINALS) for v in out if v)


def _word_start_guard() -> str:
    by_len: dict[int, list[str]] = {}
    for v in _lead_variants():
        by_len.setdefault(len(v), []).append(v)
    alts = [r"(?<![\u05D0-\u05EA])"]
    for n in sorted(by_len):
        alts.append(r"(?<=(?<![\u05D0-\u05EA])(?:" + "|".join(by_len[n]) + "))")
    return "(?:" + "|".join(alts) + ")"


_WSG = _word_start_guard()


def _guard(part: str) -> str:
    return _WSG + "(?:" + part + ")" if _HEB_START.match(part) else part


def _rx(*parts: str) -> re.Pattern[str]:
    return _c("|".join(_guard(p) for p in parts))


# ═══════════════════════════ אותות ═══════════════════════════

# מנהל 248 (qa2 xq2-38, qa3 xq3-08): חשד להונאה — «אמיתי או ספאם?», «מפחד לפתוח את הקישור», «is this a scam?»
# ⇒ who_is_this (זיהוי העסק) + תג phishing_concern וכרטיס לבעל העסק. לא שולחים קישור תשלום למי שחושש ממנו.
_PHISH = (r"(?<![\w])(?:ה)?(?:ספאם|ספמ|עוקצ|פישינג|הונאה|נוכלות)(?![\w])\W*\?|אמיתי\w*\s+או\s+(?:ספאם|ספמ|הונאה|עוקצ|מזויפ\w*|פישינג)"
          r"|(?:זה|זאת|זו|ההודעה|הקישור|הלינק|המייל)\s+(?:\w+\s+)?(?:ספאם|ספמ|עוקצ|הונאה|פישינג|מזויפ\w*)(?![\w])"
          r"|(?:מפחד|מפחדת|חושש|חוששת|פוחד|פוחדת|לא בטוח\w*|לא סומכ\w*)\s+(?:\w+\s+){0,2}?(?:לפתוח|ללחוצ|להיכנס|לשלמ דרכ)"
          r"|\b(?:is\s+this|is\s+it|looks\s+like)\s+(?:a\s+)?(?:scam|spam|phishing|fraud|legit\w*|real)\b|\bphishing\b")
