# ═══════════════════════════ חילוץ ישויות ═══════════════════════════
_NUM_WORDS = {
    "אחד": 1, "אחת": 1, "שניים": 2, "שנים": 2, "שתיים": 2, "שתים": 2, "שני": 2, "שתי": 2,
    "שלוש": 3, "שלושה": 3, "ארבע": 4, "ארבעה": 4, "חמש": 5, "חמישה": 5, "שש": 6, "שישה": 6,
    "שבע": 7, "שבעה": 7, "שמונה": 8, "תשע": 9, "תשעה": 9, "עשר": 10, "עשרה": 10,
    "אחת עשרה": 11, "שתים עשרה": 12, "שנים עשר": 12, "שתיים עשרה": 12,
}
_NUM_WORDS = {k.translate(_FINALS): v for k, v in _NUM_WORDS.items()}
_NUMW = "|".join(sorted(_NUM_WORDS, key=len, reverse=True))
_INST_RX = _c(
    r"(?:ב-?|ל-?)?(\d{1,2}|" + _NUMW + r")\s*(?:-\s*)?(?:תשלומים|תשלומי|חלקים|פעמים|פעימות|חודשים|חודשי|צ'?קים|צ'?יקים|צקים|installments)"
    r"|(?:תשלומים|פריסה|לפרוס|לחלק)\s*(?:ל|ב)-?\s*(\d{1,2}|" + _NUMW + r")(?!\s*(?:₪|ש\"ח|שקל|ש'|ימים|יום|לחודש|בחודש))")
_HALF_RX = _c(r"חצי (?:עכשיו|היום|החודש) ו?(?:חצי|השאר|את השאר)")


def extract_installments(t: str) -> int | None:
    if _HALF_RX.search(t):
        return 2
    m = _INST_RX.search(t)
    if not m:
        e = _EN_INST_RX.search(t)
        if not e:
            return None
        g = e.group(1).lower()
        n = int(g) if g.isdigit() else _EN_INST.get(g, 0)
        return n if 1 <= n <= 36 else None
    g = (m.group(1) or m.group(2) or "").strip()
    if g.isdigit():
        n = int(g)
    else:
        n = _NUM_WORDS.get(g, 0)
    return n if 1 <= n <= 36 else None


_MONTHLY_RX = _c(r"(\d{1,3}(?:,\d{3})+|\d{2,})\s*(?:₪|ש\"ח|שח|שקל\w*)?\s*(?:כל חודש|בכל חודש|לחודש|בחודש(?! ה))")


# מנהל 268: סכום חודשי באנגלית — «200 a month», «200 per month», «₪200/month», «200 monthly». היה: לא זוהה בכלל
# («can we do 200 a month?» ⇒ «לא ברור», גם באמצע הצעת פריסה). רק 3 ספרות ומעלה או מטבע מפורש (כמו בעברית).
_MONTHLY_EN_RX = _c(r"(?:₪|\$|nis\s*|ils\s*)?(\d{1,3}(?:,\d{3})+|\d{2,})\s*(?:₪|nis|ils|shekels?|dollars?|\$)?\s*"
                    r"(?:(?:a|per|each|every)\s+month\b|/\s*(?:month|mo)\b|monthly\b)")


def extract_monthly_amount(t: str) -> int | None:
    """"300 כל חודש" ⇒ 30000 אגורות. גם באנגלית: «200 a month» (מנהל 268)."""
    # «אפשר ב-20 לחודש?» / «עד ה-15 בחודש» = יום בחודש, לא ₪20 לחודש (היה: «ביקש/ה 60 תשלומים»)
    m = next((x for x in _MONTHLY_RX.finditer(t)
              if not (int(x.group(1).replace(",", "")) <= 31 and _s(r"(?:(?<![\w])(?:ב|עד|ל)\s*-?\s*(?:ה-?)?)$", t[:x.start()]))),
             None)
    e = _MONTHLY_EN_RX.search(t)
    if e and (not m or e.start() < m.start()):
        m = e
    if not m:
        return None
    v = int(m.group(1).replace(",", ""))
    return v * 100 if 10 <= v <= 1_000_000 else None


_AMOUNT_RX = _c(r"(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{1,2}))?\s*(?:₪|ש\"ח|שח|שקלים|שקל|nis|ils)?")
_PAID_AMOUNT_RX = _c(
    r"(?:שילמ\w*|שלמת\w*|העבר\w*|הפקד\w*|שלחת\w*|שולמ\w*|שולם|נתתי|מסרתי)\s*(?:לכם |לך |כבר |רק |בינתיים |את )*"
    r"(?:ב-?(?:ביט|פייבוקס|העברה)\s*)?(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{1,2}))?\s*(₪|ש\"ח|שח|שקלים|שקל)?")
# מנהל 271: סכום ששולם באנגלית — «I paid 1000» / «I paid 1500 nis» (חוב 5,000) ⇒ היה «טוען/ת ששילם/ה 5,000 ₪»
# (מלוא החוב, בלי «חלקי») כי רק הפעלים העבריים נקראו. דולר מפורש ⇒ לא מחולץ (המטבע של החוב שקלי; לא ממירים).
_PAID_AMOUNT_EN_RX = _c(
    r"\b(?:paid|payed|transferred|wired|deposited|sent)\s+(?:(?:you|u|it|over|already|just|only|about|around|like)\s+)*"
    r"(?:(?:via|by|with|through)\s+(?:bit|paybox|bank\s+transfer|transfer|credit\s+card|card|cash|check|cheque)\s+)?"
    r"(₪|\$|nis\s*|ils\s*)?(\d{1,3}(?:,\d{3})+|\d+)(?:\.(\d{1,2}))?\s*(₪|nis|ils|shekels?|dollars?|usd|\$)?")
_PARTIAL_WORDS = _c(r"(?<![\w])(?:חלק|חלקי|חצי|מקדמה|רק חלק|את רוב|קצת|חלק מה)"
                    r"|\b(?:half|part\s+of|partial(?:ly)?|a\s+portion|a\s+deposit|down\s*payment|some\s+of\s+it)\b")


def extract_paid_amount(t: str) -> int | None:
    for m in _PAID_AMOUNT_RX.finditer(t):
        after = t[m.end():m.end() + 12]
        if _m(r"\s*(?:תשלומים|ימים|יום|לחודש|בחודש|\.\d|/)", after):
            continue
        whole = int(m.group(1).replace(",", ""))
        frac = int((m.group(2) or "0").ljust(2, "0"))
        if whole == 0 or whole > 10_000_000:
            continue
        return whole * 100 + frac
    for m in _PAID_AMOUNT_EN_RX.finditer(t):
        cur = ((m.group(1) or "") + (m.group(4) or "")).strip()
        if cur in ("$", "dollar", "dollars", "usd") or any(c in cur for c in ("$", "dollar", "usd")):
            continue
        after = t[m.end():m.end() + 20]
        # «paid 2 payments», «paid 3 days ago», «sent 200 a month», «paid 1.5», «paid 10/11»
        if _m(r"\s*(?:payments?|installments?|instalments?|days?|weeks?|months?|years?|hours?|times?|messages?|emails?|"
              r"texts?|photos?|pictures?|screenshots?|(?:a|per|each|every)\s+month|monthly|\.\d|/|st\b|nd\b|rd\b|th\b|am\b|pm\b|:)",
              after):
            continue
        whole = int(m.group(2).replace(",", ""))
        frac = int((m.group(3) or "0").ljust(2, "0"))
        if whole == 0 or whole > 10_000_000 or (not cur and 1990 <= whole <= 2100 and "," not in m.group(2)
                                                  and _s(r"\b(?:in|since|from)\s*$", t[:m.start(2)])):
            continue
        return whole * 100 + frac
    return None


_WEEKDAYS = {"ראשון": 6, "שני": 0, "שלישי": 1, "רביעי": 2, "חמישי": 3, "שישי": 4}


_WEEKDAYS = {k.translate(_FINALS): v for k, v in _WEEKDAYS.items()}


def _next_weekday(today: date, wd: int) -> date:
    """המופע הבא של היום (לעולם לא היום עצמו)."""
    return today + timedelta(days=(wd - today.weekday()) % 7 or 7)


def _next_weekday_he(today: date, wd: int, nx: str) -> tuple[date | None, bool]:
    """מנהל 262: «שלישי הבא» כשהשלישי הזה עוד לפנינו *באותו שבוע* (ראשון–שבת) — שתי קריאות שגורות: השלישי הזה
    או של השבוע הבא. ניחוש מוקדם ⇒ תזכורת לפני המועד שהלקוח התכוון אליו (טעות בטוחה-בעצמה) ⇒ מעורפל ⇒ «עד איזה תאריך?».
    «הקרוב», בלי סיומת, או יום שכבר עבר השבוע ⇒ המופע הבא (ללא שינוי)."""
    nxt = _next_weekday(today, wd)
    if nx in ("הבא", "next") and (wd + 1) % 7 > (today.weekday() + 1) % 7:
        return None, True
    return nxt, False


def _weekday_with_day(today: date, wd: int, day: int) -> tuple[date | None, bool]:
    """מנהל 254: «ביום שלישי ה-17» / «Tuesday the 17th» — היום בחודש קובע, לא «שלישי הקרוב».
    עד 254: כלל היום-בשבוע רץ קודם ⇒ «בעצם ביום שלישי ה-17» נרשם כ-10.11 (טעות בטוחה-בעצמה, תזכורת שבוע מוקדם).
    יום בשבוע ויום בחודש לא מתאימים זה לזה (או יום לא קיים) ⇒ מעורפל ⇒ «עד איזה תאריך?» — לא מנחשים."""
    if not 1 <= day <= 31:
        return None, True
    y, m = today.year, today.month
    for _ in range(2):  # החודש הנוכחי (אם היום עוד לא עבר) או הבא
        if day > today.day or (y, m) != (today.year, today.month):
            try:
                cand = date(y, m, day)
            except ValueError:
                cand = None
            if cand is not None:
                return (cand, False) if cand.weekday() == wd else (None, True)
        m += 1
        if m > 12:
            y, m = y + 1, 1
    return None, True


def _month_day(today: date, day: int) -> date:
    y, m = today.year, today.month
    if day <= today.day:
        m += 1
        if m > 12:
            y, m = y + 1, 1
    return date(y, m, min(day, calendar.monthrange(y, m)[1]))


