_EN_NUM = {"a": 1, "one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "ten": 10,
           "a couple of": 2, "couple of": 2, "a couple": 2}


# מנהל 252: חודש בשם — «ב-15 בדצמבר», «עד ה-1 לינואר», «בסוף דצמבר», «the 3rd of January», «Dec 5th».
# לפני כן: בעברית ⇒ אין תאריך בכלל (כרטיס לבעל העסק / «עד מתי?» שוב); באנגלית «the 3rd of January» ⇒ 3 בדצמבר
# (החודש נבלע ע״י «the Nth») ⇒ תזכורת חודש לפני המועד שהלקוח ביקש. תאריך שעבר לפני ≤90 יום = אזכור עבר
# («שילמתי ב-10 בנובמבר»), לא הבטחה ⇒ מדלגים; ישן יותר ⇒ השנה הבאה («ב-3 בינואר» בנובמבר). חודש בלי יום ⇒ מעורפל.
_HE_MONTHS = {"ינואר": 1, "פברואר": 2, "מרצ": 3, "מרס": 3, "אפריל": 4, "מאי": 5, "יוני": 6, "יולי": 7,
              "אוגוסט": 8, "ספטמבר": 9, "אוקטובר": 10, "נובמבר": 11, "דצמבר": 12}
_HE_MON = "|".join(sorted(_HE_MONTHS, key=len, reverse=True))
_HE_DAYW = {**_NUM_WORDS, **{k.translate(_FINALS): v for k, v in {"ראשון": 1, "חמישה עשר": 15, "חמש עשרה": 15,
                                                                    "עשרים": 20, "שלושים": 30}.items()}}
# מנהל 253 (qa9 q9-17): «בעשרים ושלושה בנובמבר» ⇒ אין תאריך (רק «עשרים» לבד היה מוכר). מספרים מורכבים 11–31.
_HE_UNITS = {"אחד": 1, "אחת": 1, "שניים": 2, "שתיים": 2, "שלושה": 3, "שלוש": 3, "ארבעה": 4, "ארבע": 4, "חמישה": 5,
             "חמש": 5, "שישה": 6, "שש": 6, "שבעה": 7, "שבע": 7, "שמונה": 8, "תשעה": 9, "תשע": 9}
for _w, _v in _HE_UNITS.items():
    _HE_DAYW[("עשרים ו" + _w).translate(_FINALS)] = 20 + _v
    if _v == 1:
        _HE_DAYW[("שלושים ו" + _w).translate(_FINALS)] = 31
    if _v >= 3:   # 13–19, זכר ונקבה («שלושה עשר», «שמונה עשרה»); 11, 12 כבר ב-_NUM_WORDS
        for _suf in (" עשר", " עשרה"):
            _HE_DAYW[(_w + _suf).translate(_FINALS)] = 10 + _v
_HE_DAYW_RX = "|".join(sorted(_HE_DAYW, key=len, reverse=True))
_EN_MONTHS = {"january": 1, "february": 2, "march": 3, "april": 4, "may": 5, "june": 6, "july": 7, "august": 8,
              "september": 9, "october": 10, "november": 11, "december": 12, "jan": 1, "feb": 2, "mar": 3, "apr": 4,
              "jun": 6, "jul": 7, "aug": 8, "sept": 9, "sep": 9, "oct": 10, "nov": 11, "dec": 12}
_EN_MON = "|".join(sorted(_EN_MONTHS, key=len, reverse=True))
_PAST_REF_DAYS = 90


def _named_date(today: date, mo: int, day: int | None, part: str = "") -> date | None:
    """יום בחודש בשם ⇒ המופע הקרוב. part: start/mid/end כשאין יום. None = לא חוקי או אזכור עבר."""
    for y in (today.year, today.year + 1):
        last = calendar.monthrange(y, mo)[1]
        d = day if day is not None else {"start": 1, "mid": 15, "end": last}[part]
        if not 1 <= d <= last:
            if y == today.year and day is not None and day <= 31 and mo != 2:
                return None  # «31 בנובמבר» — לא קיים בשום שנה
            continue
        cand = date(y, mo, d)
        if cand >= today:
            return cand
        if (today - cand).days <= _PAST_REF_DAYS:
            return None
    return None


def _named_month_he(t: str, today: date) -> tuple[date | None, bool] | None:
    day_rx = r"(\d{1,2}|(?<![\w])(?:ב|ה|ל)?-?(?:" + _HE_DAYW_RX + r"))"
    m = _s(r"(?<![\d.,/])" + day_rx + r"\s*-?\s*(?:(?:ב|ל)חודש\s+|של\s+)?(?:ב|ל)?-?\s?(" + _HE_MON + r")(?![\w])", t)
    if m:
        g = re.sub(r"^(?:ב|ה|ל)?-?", "", m.group(1)) if not m.group(1).isdigit() else m.group(1)
        day = int(g) if g.isdigit() else _HE_DAYW.get(g)
        d = _named_date(today, _HE_MONTHS[m.group(2)], day) if day else None
        return (d, False) if d else None  # יום+חודש שעבר = אזכור עבר, לא «מעורפל»
    m = _s(r"(?<![\w])(?:ב|עד )?(" + _HE_MON + r")\s+(\d{1,2})(?![\d.,/])", t)
    if m:
        d = _named_date(today, _HE_MONTHS[m.group(1)], int(m.group(2)))
        return (d, False) if d else None
    m = _s(r"(?<![\w])(?:ב|עד |ל)?(תחילת|ראשית|אמצע|סופ)\s+(?:חודש\s+)?(" + _HE_MON + r")(?![\w])", t)
    if m:
        part = {"תחילת": "start", "ראשית": "start", "אמצע": "mid", "סופ": "end"}[m.group(1)]
        d = _named_date(today, _HE_MONTHS[m.group(2)], None, part)
        if d:
            return d, False
    # חודש בלי יום ⇒ מעורפל. «יוני»/«מאי» בלי מילת יחס = שם/מילה («יוני אמר», «מאי נפקא מינה»)
    m = _s(r"(?<![\w])(ב|ל|עד |מ|אחרי |לפני |לקראת |במהלכ |ה)?-?(" + _HE_MON + r")(?![\w])", t)
    if m and (m.group(1) or m.group(2) not in ("יוני", "מאי")):
        return None, True
    return None


def _named_month_en(t: str, today: date) -> tuple[date | None, bool] | None:
    m = re.search(r"\b(?:the\s+)?(\d{1,2})(st|nd|rd|th)?\s+(of\s+)?(" + _EN_MON + r")\b\.?", t)
    if m and not (m.group(4) == "may" and not (m.group(2) or m.group(3))):
        return _named_date(today, _EN_MONTHS[m.group(4)], int(m.group(1))), False  # None = אזכור עבר ⇒ לא «the Nth»
    # מנהל 253 (qa9 q9-20): «May 10» כהודעה שלמה (תשובה ל«עד מתי?») ⇒ תאריך; «may» לבד בתוך משפט נשאר מלכודת
    m = re.fullmatch(r"\W*may\s+(\d{1,2})\W*", t)
    if m:
        return _named_date(today, 5, int(m.group(1))), False
    m = re.search(r"(?:\b(on|by|until|till|before|from)\s+)?\b(" + _EN_MON + r")\b\.?\s+(?:the\s+)?(\d{1,2})(st|nd|rd|th)?\b(?![:.]\d)", t)
    if m and not (m.group(2) == "may" and not (m.group(1) or m.group(4))):
        return _named_date(today, _EN_MONTHS[m.group(2)], int(m.group(3))), False
    m = re.search(r"\b(early|beginning\s+of|start\s+of|first\s+week\s+of|mid|middle\s+of|end\s+of|late)\s*-?\s*(?:the\s+month\s+of\s+)?("
                  + _EN_MON + r")\b", t)
    if m and not (m.group(2) == "may" and m.group(1) in ("early", "late", "mid")):
        g = m.group(1)
        part = "start" if g.startswith(("early", "beginning", "start", "first")) else "mid" if g.startswith("mid") else "end"
        d = _named_date(today, _EN_MONTHS[m.group(2)], None, part)
        if d:
            return d, False
    if re.search(r"\b(?:in|by|until|till|before|after|around|during|sometime\s+in|end\s+of|early|late)\s+(?:" + _EN_MON + r")\b", t) \
            and not re.search(r"\b(?:in|by|until|till|before|after|around|during)\s+may\s+(?:be|i|we|have|not|pay)\b", t):
        return None, True
    return None


def _extract_date_en(t: str, today: date) -> tuple[date | None, bool] | None:
    if not re.search(r"[a-z]", t):
        return None
    if re.search(r"\bday\s+after\s+tomorrow\b", t):
        return today + timedelta(days=2), False
    if re.search(r"\b(?:tomorrow|tmrw|tmr|2morrow)\b", t):
        return today + timedelta(days=1), False
    if re.search(r"\b(?:today|tonight|this\s+(?:evening|afternoon)|later\s+today|right\s+now|by\s+end\s+of\s+day)\b", t):
        return today, False
    m = re.search(r"\b(?:in|within)\s+(\d{1,2}|a couple of|couple of|a couple|a|one|two|three|four|five|six|seven|ten)\s+(days?|weeks?)\b", t)
    if m:
        g = m.group(1)
        n = int(g) if g.isdigit() else _EN_NUM[g]
        return today + timedelta(days=n * (7 if m.group(2).startswith("week") else 1)), False
    named = _named_month_en(t, today)
    if named is not None and not named[1]:
        return named
    m = re.search(r"\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\s*,?\s*(?:the\s+)?(\d{1,2})(?:st|nd|rd|th)?\b(?![.:/]\d)"
                  r"(?!\s*(?:payments|installments|days|weeks|months|dollars|shekels|nis|%))", t)
    if m:
        return _weekday_with_day(today, _EN_WD[m.group(1)], int(m.group(2)))
    m = re.search(r"\b(?:(on|by|this|next|until|till|before)\s+)?(?:on\s+|by\s+)?(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b", t)
    if m and not re.search(r"\b(?:last|every)\s+" + m.group(2), t):
        return _next_weekday_he(today, _EN_WD[m.group(2)], "next" if m.group(1) == "next" else "")
    m = re.search(r"\b(?:on|by|until|till|before)?\s*the\s+(\d{1,2})(?:st|nd|rd|th)\b", t) or \
        re.search(r"\b(?:on|by|until|till|before)\s+(\d{1,2})(?:st|nd|rd|th)\b", t)
    if m and 1 <= int(m.group(1)) <= 31:
        # מנהל 255: «the 20th of next month» ⇒ היה 20 בחודש *הזה* (חודש מוקדם מדי, בביטחון)
        if re.match(r"\s+of\s+(?:the\s+)?next\s+month\b|\s+next\s+month\b", t[m.end():]):
            y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
            return date(y, mo, min(int(m.group(1)), calendar.monthrange(y, mo)[1])), False
        return _month_day(today, int(m.group(1))), False
    if re.search(r"\b(?:by\s+|at\s+|before\s+|until\s+|till\s+)?(?:the\s+)?end\s+of\s+(?:the|this)\s+month\b", t):
        last = date(today.year, today.month, calendar.monthrange(today.year, today.month)[1])
        if (last - today).days < 3:
            y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
            last = date(y, mo, calendar.monthrange(y, mo)[1])
        return last, False
    if re.search(r"\bnext\s+week\b", t):
        return _next_weekday(today, 6), False
    if re.search(r"\b(?:next\s+month|beginning\s+of\s+(?:next|the\s+next)\s+month|start\s+of\s+next\s+month|early\s+next\s+month)\b", t):
        y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
        # עקבי עם העברית: «בחודש הבא» ⇒ 10 בחודש, «בתחילת החודש הבא» ⇒ 1 (ביקורת qa9 q9-28)
        bare = not re.search(r"\b(?:beginning|start|early)\b", t)
        return date(y, mo, 10 if bare else 1), False
    if named is not None:
        return named
    if re.search(r"\b(?:soon|asap|in\s+a\s+few\s+days|next\s+few\s+days|this\s+week|payday|when\s+i\s+get\s+paid|"
                 r"after\s+(?:my\s+)?(?:salary|paycheck)|when\s+(?:my\s+)?(?:salary|paycheck)|later\s+this\s+(?:week|month))\b", t):
        return None, True
    return None


# מנהל 253 (qa9 q9-19): «אחרי חנוכה» / «לפני פסח» כתשובה ל«עד מתי?» ⇒ «לא ברור» וכרטיס לבעלים. זה מועד מעורפל
# (אין לוח עברי במנוע) ⇒ שואלים «עד איזה תאריך בערך?».
_HOLIDAY_VAGUE = (r"(?:אחרי|לפני|אחר|עד|ב|מיד אחרי|לקראת)\s*-?\s*(?:ה)?(?:חנוכה|פסח|סוכות|פורים|שבועות|ראש השנה"
                  r"|יום כיפור|ט\"?ו בשבט|ל\"?ג בעומר|החגים|החג)(?![\w])")
# מנהל 257: חודש עברי («אשלם בטבת», «עד שבט», «בסוף כסלו», «ב-10 בטבת») ⇒ מעורפל, לא תאריך (אין המרה עברית⇄לועזית
# במנוע; עדיף לשאול «עד איזה תאריך?» מאשר לנחש). היה: «בכסלו» כתשובה ל«עד מתי?» ⇒ «לא ברור» וכרטיס לבעלים.
# «אב» לבד רק אחרי ב/עד (בלי ל — «לאב» = לאבא), ובצורה «מנחם אב».
_HEB_MONTH_VAGUE = (r"(?:(?:אחרי|לפני|עד|ב|לקראת|בסוף|עד סוף|בתחילת|עד תחילת|באמצע|במהלך)\s*-?\s*(?:ה)?(?:חודש\s+)?"
                    r"(?:תשרי|חשוון|חשון|מרחשוון|מרחשון|כסלו|כסליו|טבת|שבט|אדר(?:\s*[אב]'?(?![\w]))?|ניסן|אייר|סיוון|סיון"
                    r"|תמוז|מנחם[- ]?אב|אלול)|(?:ב|עד\s+)אב)(?![\w])")
_NEXT_WD_VAGUE = r"(?<![\w])(?:ראשון|שני|שלישי|רביעי|חמישי|שישי)\s+(?:ה)?הבא(?![\w])"
_NEXT_WD_VAGUE_EN = r"\bnext\s+(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b"
_HOLIDAY_VAGUE = r"(?:" + _HOLIDAY_VAGUE + r"|" + _HEB_MONTH_VAGUE + r")"


def extract_date(t: str, today: date) -> tuple[date | None, bool]:
    """מחזיר (תאריך, מעורפל?). מעורפל = יש כוונה לתאריך אבל אי אפשר לקבע אותו."""
    en = _extract_date_en(t, today)
    if en is not None and en[0] is not None:
        return en
    if _s(r"(?<![\w])(?:מחרתיים)", t):
        return today + timedelta(days=2), False
    if _s(r"(?<![\w])(?:עד |כבר )?מחר(?![\w])", t):
        return today + timedelta(days=1), False
    # מנהל 260: «אני בעבודה עכשיו» / «עסוקה כרגע» = למה לא עכשיו, לא מועד תשלום (היה promise=היום ב-AWAITING_DATE)
    if _s(r"(?<![\w])(?:עכשיו|מיד|תיכף|בדקות הקרובות)(?![\w])",
          re.sub(_c(r"(?:בעבודה|עסוק\w*|בפגישה|בנהיגה|נוהג\w*|בדרכ|בחוצ לארצ|לא (?:יכול|יכולה|זמין|זמינה) (?:לדבר|לענות))\s+(?:\w+\s+)?עכשיו(?![\w])"), " ", t)):
        return today, False
    if _s(r"(?<![\w])(?:עוד |עד |כבר )?היום(?![\w])|(?<![\w])עוד מעט|בשעות הקרובות|הערב(?![\w])", t):
        return today, False
    m = _s(r"(?:בעוד|תוך|עוד)\s+(\d{1,2}|" + _NUMW + r")\s*(ימים|יום|שבועות|שבוע)", t)
    if m:
        g = m.group(1)
        n = int(g) if g.isdigit() else _NUM_WORDS.get(g, 0)
        return today + timedelta(days=n * (7 if m.group(2).startswith("שבוע") else 1)), False
    if _s(r"(?:בעוד|תוך|עוד)\s+(?:כ)?חודשיים", t):
        return today + timedelta(days=60), False
    if _s(r"(?:בעוד|תוך|עוד)\s+(?:כ)?יומיים", t):
        return today + timedelta(days=2), False
    if _s(r"(?:בעוד|תוך|עוד)\s+(?:כ)?שבועיים", t):
        return today + timedelta(days=14), False
    if _s(r"(?:בעוד|תוך|עוד)\s+(?:כ)?שבוע(?!\w)", t) or _s(r"(?:תנו|תן|תני) לי (?:עוד )?שבוע", t):
        return today + timedelta(days=7), False
    if _s(r"(?:תנו|תן|תני) לי (?:עוד )?שבועיים", t):
        return today + timedelta(days=14), False
    if _s(r"(?:בעוד|תוך|עוד)\s+(?:כ)?חודש(?!\w)|(?:תנו|תן|תני) לי (?:עוד )?חודש", t):
        return today + timedelta(days=30), False
    he_named = _named_month_he(t, today)
    if he_named is not None and he_named[0] is not None:
        return he_named
    wd_dom = _s(r"(ראשון|שני|שלישי|רביעי|חמישי|שישי)\s*,?\s*(?:ה|ב)?-?(\d{1,2})(?![\d./:]|\s*(?:תשלומ|ש\"?ח|₪|שקל|אלף|חשבונ|ימים|יום|שבוע|חודש|%))", t)
    if wd_dom:
        return _weekday_with_day(today, _WEEKDAYS[wd_dom.group(1)], int(wd_dom.group(2)))
    m = _s(r"(?:(?:עד |ב|ל)?יום |ב|עד ה?|ל)-?(ראשון|שני|שלישי|רביעי|חמישי|שישי)(?![\w])(?:\s+(?:ה)?(הבא|הקרוב)(?![\w]))?", t)
    if m and not _s(r"(?:תשלום|חלק) (?:ה)?" + m.group(1), t):
        return _next_weekday_he(today, _WEEKDAYS[m.group(1)], m.group(2) or "")
    m = _s(r"(\d{1,2})[./](\d{1,2})(?:[./](\d{2,4}))?", t)
    if m:
        d, mo = int(m.group(1)), int(m.group(2))
        y = int(m.group(3)) if m.group(3) else today.year
        if y < 100:
            y += 2000
        try:
            cand = date(y, mo, d)
            if not m.group(3) and cand < today:
                cand = date(y + 1, mo, d)
            return cand, False
        except ValueError:
            pass
    m = _s(r"(?:ב|עד ה?)-?(\d{1,2})\s*(?:ל|ב)(?:ה)?(?:חודש)(?:\s+(?:ה)?(הבא))?", t)
    if m and 1 <= int(m.group(1)) <= 31:
        if m.group(2):   # מנהל 255: «ב-23 לחודש הבא» ⇒ היה 23 בחודש *הזה* (טעות בטוחה-בעצמה, חודש מוקדם מדי)
            y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
            return date(y, mo, min(int(m.group(1)), calendar.monthrange(y, mo)[1])), False
        return _month_day(today, int(m.group(1))), False
    if _s(r"(?:בתחילת|עד תחילת|בראשית) (?:ה)?חודש (?:ה)?(?:הבא|הקרוב)?|בחודש הבא|חודש הבא", t):
        y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
        return date(y, mo, 10 if "חודש הבא" in t and "תחילת" not in t else 1), False
    if _s(r"(?:בסוף|עד סוף) (?:ה)?חודש", t):
        last = date(today.year, today.month, calendar.monthrange(today.year, today.month)[1])
        if (last - today).days < 3:
            y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
            last = date(y, mo, calendar.monthrange(y, mo)[1])
        return last, False
    # מנהל 263 (q14-22): «אעביר מתישהו שבוע הבא» ⇒ היה ראשון הבא (ניחוש בטוח); «מתישהו/במהלך/באמצע» ⇒ מעורפל
    if _s(r"(?:מתישהו|איפשהו|באיזשהו שלב|במהלכ|באמצע)\s+(?:ה|ב)?שבוע (?:ה)?הבא", t):
        return None, True
    if _s(r"(?:בשבוע הבא|שבוע הבא)", t):
        return _next_weekday(today, 6), False
    if _s(r"(?:" + _HOLIDAY_VAGUE + r"|משכורת|אחרי החג|אחרי החגים|כשאקבל|כשיהיה|כשיהיה לי|בקרוב|בהקדם|בימים הקרובים|"
                 r"כמה ימים|מתישהו|אחרי שאקבל|לקראת|כשאחזור|כשאסתדר)", t):
        return None, True
    if he_named is not None:
        return he_named
    return en or (None, False)  # מעורפל באנגלית רק אם אין תאריך עברי מדויק


# מנהל 255: יום בחודש לבד כתשובה ל«עד מתי?» — «ב-23», «עד ה-17», «17», «בעשרים», «the 17th» ⇒ היה «לא ברור» וכרטיס
# לבעלים, אף שהלקוח ענה בדיוק על השאלה. רק בהקשר (AWAITING_DATE; ב-PROMISED רק עם מילת יחס — עדכון מועד), ורק כשכל
# ההודעה היא התאריך (+ מילות מילוי) ⇒ «ב-3 תשלומים», «שילמתי 17», «ב-500» לא נתפסים. בלי הקשר ⇒ ביט-זהה.
_EN_ORDW = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8,
            "ninth": 9, "tenth": 10, "eleventh": 11, "twelfth": 12, "thirteenth": 13, "fourteenth": 14,
            "fifteenth": 15, "sixteenth": 16, "seventeenth": 17, "eighteenth": 18, "nineteenth": 19, "twentieth": 20,
            "thirtieth": 30}
for _w, _v in list(_EN_ORDW.items())[:9]:
    _EN_ORDW[f"twenty {_w}"] = _EN_ORDW[f"twenty-{_w}"] = 20 + _v
_EN_ORDW["thirty first"] = _EN_ORDW["thirty-first"] = 31
_EN_ORDW_RX = "|".join(sorted(_EN_ORDW, key=len, reverse=True))
_BARE_LEAD_HE = (r"(?:(?:אז|אולי|נגיד|בערך|כנראה|טוב|אוקיי|אוקי|סבבה|בסדר|כן|יאללה|בעצם|רגע|סליחה|תיקון|אני חושב|אני חושבת"
                 r"|אשלם|אעביר|אסדר|אפקיד|נשלם|נעביר|נסדר|אשתדל|אנסה|עד|כנראה רק|רק|בערך|משהו כמו|נגיד ש"
                 # מנהל 256: «אני אשלם הכל ב-30», «אעביר את היתרה ב-20»
                 r"|אני|אנחנו|הכל|הכול|את הכל|את הכול|את זה|את החוב|את היתרה|את התשלום|את הסכום)\W*)*")
_BARE_TAIL_HE = r"(?:\W*(?:בסדר|אוקיי|אוקי|תודה|בערך|בעזרת ה'?|בע\"?ה|אם אפשר|אם זה בסדר|זה בסדר|אפשר|מקווה|נראה לי))*\W*"
_BARE_DAY_HE = (r"(?:(?:עד|על|ביום|עד יום|לקראת|בסביבות|סביבות|באזור)\s*)?(?P<pre>ב|ה|ל|בה|לה|עד ה)?-?\s*"
                r"(?P<d>\d{1,2}(?!\d|[.,/:]\d)|(?:" + _HE_DAYW_RX + r")(?![\w]))"
                r"(?:\s*(?:ב|ל)?(?:ה)?חודש(?:\s+(?:ה)?(?P<nx>הבא|הקרוב|הזה))?)?"
                r"(?:\s+(?:בערב|בבוקר|בצהריים|בלילה|הקרוב|הזה))?")
_BARE_DAY_EN = (r"(?:(?:ok|okay|maybe|probably|around|about|um|uhh?|i'?ll\s+pay|i\s+will\s+pay|i'?ll\s+transfer|pay|actually"
                r"|let'?s\s+say|say|sorry)\W*)*(?P<prep>on|by|until|till|before|around)?\s*(?:the\s+)?"
                r"(?:(?P<d>\d{1,2})(?P<ord>st|nd|rd|th)?|(?P<w>" + _EN_ORDW_RX + r"))"
                r"(?:\s+of\s+(?:the\s+)?(?P<nx>next|this)\s+month)?(?:\W*(?:ok|okay|thanks|thank\s+you|if\s+that'?s\s+ok|please))*\W*")


def _bare_day(t: str, today: date, need_marker: bool = False) -> date | None:
    """יום בחודש לבד (כל ההודעה). need_marker: חובה מילת יחס/סיומת סודרת — לא «17» לבד."""
    m = re.fullmatch(_c(_BARE_LEAD_HE + _BARE_DAY_HE + _BARE_TAIL_HE), t)
    if m:
        g = m.group("d")
        day = int(g) if g.isdigit() else _HE_DAYW.get(g)
        marked = bool(m.group("pre")) or not g.isdigit() or bool(re.search(_c(r"(?:עד|על|ביום|חודש)"), m.group(0)))
        nx = m.group("nx")
    else:
        m = re.fullmatch(_BARE_DAY_EN, t) if re.search(r"[a-z]", t) else None
        if not m:
            return None
        day = int(m.group("d")) if m.group("d") else _EN_ORDW.get(re.sub(r"\s+", " ", m.group("w") or ""))
        marked = bool(m.group("prep") or m.group("ord") or m.group("w") or m.group("nx"))
        nx = {"next": "הבא", "this": "הזה"}.get(m.group("nx") or "")
    if not day or not 1 <= day <= 31 or (need_marker and not marked):
        return None
    if nx in ("הבא",):
        y, mo = (today.year + 1, 1) if today.month == 12 else (today.year, today.month + 1)
        return date(y, mo, min(day, calendar.monthrange(y, mo)[1]))
    return _month_day(today, day)


# ═══ מנהל 263 (סט QA #14) · צורות הבטחה שלא נתפסו ═══
# «ב20 אני משלמת» (תאריך לפני הפועל), «next tuesday אנימשלמת» (אני צמוד), «אשלם בביט ב-19» (אמצעי תשלום בין הפועל
# ליום), «אשלם שני הבא» (יום בשבוע בלי «ב»/«ביום»). מנרמלים לצורה שהכללים הקיימים כבר מכירים — רק להבטחה ותאריך.
_PV_HE = r"(?:אשלמ|נשלמ|אעביר|נעביר|אסדר|נסדר|אפקיד|נפקיד)"
_PAY_METHOD_HE = r"(?:ב|דרכ\s+)(?:ה)?(?:ביט|פייבוקס|העברה(?: בנקאית)?|אשראי|כרטיס(?: אשראי)?|מזומנ|צ'?ק|paybox|bit)"


def _promise_prep(t: str) -> str:
    t = re.sub(_c(r"(?<![\w])(אני|אנחנו)(?=(?:משלמ|מעביר|מסדר|אשלמ|אעביר)\w*)"), r"\1 ", t)
    t = re.sub(_c(r"(?<![\w])(" + _PV_HE + r")\s+" + _PAY_METHOD_HE + r"(?![\w])"), r"\1", t)
    t = re.sub(_c(r"^\W*((?:ב|עד ה?)-?\s*\d{1,2})(?![\d./:])\s+(?:אני |אנחנו )?"
                  r"(?:משלמ|משלמת|משלמימ|מעביר|מעבירה|מעבירימ|אשלמ|אעביר|נשלמ|נעביר)(?![\w])"), r"אשלמ \1", t)
    t = re.sub(_c(r"(?<![\w])(" + _PV_HE + r")\s+(ראשונ|שני|שלישי|רביעי|חמישי|שישי)\s+(?=(?:ה)?(?:הבא|הקרוב)(?![\w]))"),
               r"\1 ביומ \2 ", t)
    return t


# מנהל 263 (STATUS 262 «הבא» AI; q14-23/26/27): הודעה ראשונה שהיא *רק* מועד, בלי פועל — «חמישי הבא», «ב-15»,
# «אחרי המשכורת, ב-1 לדצמבר» ⇒ היה «לא ברור» וכרטיס לבעלים. כל ההודעה = מילות מילוי + מועד; יום בשבוע לבד חייב
# מילת יחס («ביום», «ב») או «הבא/הקרוב» («שני» לבד יכול להיות מספר). «הבא» עמום ⇒ (None, True) ⇒ «עד איזה תאריך?».
_DATE_ONLY_LEAD = (r"^\W*(?:(?:אז|טוב|אולי|בערכ|כנראה|נגיד|רק|בסדר|אוקיי|אוקי|סבבה|כנ|יאללה"
                   r"|(?:אחרי|לאחר) (?:ה)?משכורת|כשתיכנס (?:ה)?משכורת)\W+)*")


def _date_only(t: str, today: date) -> tuple[date | None, bool] | None:
    u = re.sub(_c(_DATE_ONLY_LEAD), "", t)
    wm = _fm(r"\W*((?:(?:עד )?(?:ב)?יומ\s+)|ב)?(ראשונ|שני|שלישי|רביעי|חמישי|שישי)(?:\s+(?:ה)?(הבא|הקרוב))?\W*", u)
    if wm:
        if not (wm.group(1) or wm.group(3)):
            return None
        return _next_weekday_he(today, _WEEKDAYS[wm.group(2)], wm.group(3) or "")
    bd = _bare_day(u, today, need_marker=True)
    if bd is not None:
        return bd, False
    if _fm(r"\W*(?:ב|עד |עד ה|ה)?-?\s*\d{1,2}\s*-?\s*(?:(?:ב|ל)חודש\s+|של\s+)?(?:ב|ל)?-?\s?(?:" + _HE_MON + r")\W*", u):
        nm = _named_month_he(u, today)
        if nm is not None and nm[0] is not None:
            return nm
    return None


# מנהל 264 (qa14 q14-19, «הבא» AI): בקשת שינוי בהסדר שכבר הוצע/אושר — «can we move the first payment ל-20? לא ל-10»,
# «אפשר להזיז את התשלום הראשון ל-20?», «להוריד את התשלום החודשי ל-200». היה: «לא ברור» (כרטיס בלי הקשר),
# ו«שהתשלום השני יהיה בתחילת החודש» ⇒ הבטחה ⇒ «עד איזה תאריך?» ללקוח שכבר יש לו הסדר.
# רץ רק כשיש הסדר בשיחה (AWAITING_PLAN_REPLY / PLAN_PENDING_OWNER עם offered_plan).
_CHG_VERB = (r"(?<![\w])(?:ש|ו|ה)?(?:להזיז|להעביר|לדחות|להקדימ|לשנות|לזוז|להוריד|להפחית|להגדיל|להקטינ|לעדכנ"
             r"|תזיזו|תעבירו|תדחו|תקדימו|תשנו|תורידו|תעדכנו|נזיז|נעביר|נדחה|נשנה|נוריד|אפשר שה?תשלומ)(?![\w])"
             r"|\b(?:move|change|shift|push|postpone|reschedule|lower|reduce|delay)\b")
_CHG_OBJ = (r"(?<![\w])(?:ש|ו|ב|ל|מ|את )?(?:ה)?(?:תשלומ|תשלומימ|הסדר|פריסה|תאריכ|תאריכימ|מועד|מועדימ|סכומ)(?![\w])"
            r"|\b(?:payments?|installments?|instalments?|plan|dates?|amount)\b")
_CHG_ORD = (r"(?:ה)?תשלומ (?:ה)?(ראשונ|שני|שלישי|רביעי|חמישי|שישי|אחרונ|הבא|החודשי|הקרוב)(?![\w])"
            r"|\b(first|second|third|fourth|last|next|monthly) (?:payment|installment|instalment)\b")
_ORD_N = {"ראשונ": 1, "first": 1, "שני": 2, "second": 2, "שלישי": 3, "third": 3, "רביעי": 4, "fourth": 4,
          "חמישי": 5, "שישי": 6}
# חלופה שנדחית: «לא ל-10», «ולא ב-10», «במקום ה-10», «instead of the 10th», «not the 10th»
_CHG_NOT = (r"(?:(?<![\w])(?:ו?לא|במקומ|ולא כמו)\s+(?:ה|ב|ל|עד)?-?\s*\d{1,2}(?:[./]\d{1,2})?(?:\s*(?:ב|ל)?(?:חודש))?(?![\d\w])"
            r"|\b(?:not|instead\s+of)\s+(?:on\s+)?(?:the\s+)?\d{1,2}(?:st|nd|rd|th)?\b)")


def plan_change(t: str) -> tuple[int | None, str] | None:
    """בקשת שינוי בהסדר קיים ⇒ (מספר התשלום שמבקשים לשנות או None, סוג: 'date'|'amount'|'count'|'other').
    None ⇒ לא בקשת שינוי. שואל רק על הטקסט; ההקשר (יש הסדר) נבדק אצל הקורא."""
    om = _s(_CHG_ORD, t)
    verb = _s(_CHG_VERB, t)
    if not (verb and _s(_CHG_OBJ, t)) and not (om and _s(r"(?:ב|ל)-?\s*\d{1,2}(?![\d\w])|במקומ|יהיה|יהיו|תהיה"
                                                         r"|\b(?:on|to)\s+(?:the\s+)?\d{1,2}", t)):
        return None
    n = None
    kind = "other"
    if om:
        w = om.group(1) or om.group(2)
        n = _ORD_N.get(w)
        if w in ("החודשי", "monthly"):
            kind = "amount"
    if _s(r"(?:להוריד|להפחית|להגדיל|להקטינ|תורידו|נוריד|lower|reduce)", t) or extract_monthly_amount(t):
        kind = "amount"
    elif extract_installments(t) and _s(r"\d{1,2}\s*תשלומימ|\d{1,2}\s+(?:payments|installments)", t):
        kind = "count"
    elif kind == "other" and change_date(t, date(2000, 1, 1)) is not None:
        kind = "date"
    return n, kind


# מנהל 266: חזרה מהסדר שהלקוח כבר אישר (או שבעל העסק כבר אישר) — «אני מבטלת את ההסדר», «חזרתי בי»,
# «לא מתאים לי בסוף», «I changed my mind». רק מילים שמדברות על ההסדר עצמו; ההקשר נבדק אצל הקורא.
_RETRACT = (
    r"(?<![\w])(?:ש|ו)?(?:מבטל|מבטלת|מבטלים|לבטל|תבטלו|נבטל|ביטול|מוותר|מוותרת|לוותר)\s+(?:על\s+)?(?:\w+\s+){0,2}?"
    r"(?:את\s+)?(?:ה)?(?:הסדר|פריסה|תשלומים|הצעה|עסקה)(?![\w])"
    r"|(?<![\w])(?:חוזר|חוזרת|חוזרים|חזרתי|חזרנו)\s+(?:בי|בו|בה|בנו)(?![\w])"
    r"|(?<![\w])(?:ש|ו|כי)?(?:התחרטתי|התחרטנו|מתחרט|מתחרטת)(?![\w])"
    # מנהל 269 (qa15 q15-11): «האמת שהתחרטתי לגבי ההסדר, תבטלו אותו בבקשה» ⇒ היה הצעה חדשה (plan_request)
    r"|(?<![\w])(?:ש|ו)?(?:תבטלו|לבטל|נבטל|מבטלת|מבטל)\s+(?:לי\s+|לנו\s+)?(?:אותו|אותה)(?![\w])"
    r"|לא (?:אוכל|אצליח|נוכל|נצליח|יכול|יכולה|יכולים|מצליח|מצליחה) (?:לעמוד|לשלם)\s+(?:ב|את )?(?:ה)?(?:תשלומים|הסדר|פריסה)(?![\w])"
    r"|^\W*(?:בעצם|בסוף)\s*,?\s*לא(?![\w])"
    r"|לא (?:מתאים|מתאימה|מסתדר|מסתדרת|טוב)(?: לי| לנו)? בסוף"
    r"|לא (?:רוצה|רוצים|מעוניין|מעוניינת) (?:ב|את )?(?:ה)?(?:הסדר|פריסה|תשלומים)(?![\w])"
    r"|\bchang(?:ed|ing)\s+(?:my|our)\s+minds?\b|\bback(?:ing)?\s+out\b"
    r"|\bwithdraw\w*\s+(?:from\s+)?(?:the\s+|my\s+)?(?:plan|arrangement|agreement)\b"
    r"|\bcancel\w*\s+(?:the\s+|my\s+|this\s+|our\s+)?(?:payment\s+)?(?:plan|installments?|instalments?|arrangement|payments)\b"
    r"|\bnever\s*mind\s+(?:the\s+)?(?:plan|installments?|payments)\b")


# «אל תבטלו את ההסדר», «לא מבטלת», «לא חוזרת בי», «don't cancel» — ההפך מחזרה
_RETRACT_NEG = (r"(?<![\w])(?:לא|אל|אין|בלי)\s+(?:\w+\s+)?(?:מבטל|מבטלת|מבטלים|לבטל|תבטלו|נבטל|ביטול|חוזר|חוזרת|מוותר|מוותרת"
                r"|מתחרט|מתחרטת|צריך לבטל)(?![\w])|\b(?:don'?t|do\s+not|not|no\s+need\s+to)\s+(?:\w+\s+)?cancel\w*\b")


# מנהל 267 («הבא» AI מ-266): הצעה נגדית במספר תשלומים *אחרי* שהלקוח אישר הסדר (PLAN_PENDING_OWNER) —
# «לא מסתדר לי, אולי 6?», «3 payments is still too much, can we do 6 instead?», «4 זה הרבה, אולי 8». היה:
# «לא ברור» (כרטיס בלי הקשר), או גרוע — «לא מסתדר»/«too much» ⇒ plan_retract ⇒ «↩️ חוזר/ת בו», והבקשה הממשית (6)
# אבדה. גם ב-AWAITING_PLAN_REPLY: «too much, can we do 6 instead?» ⇒ דחייה; «6 instead» / «six instead» ⇒ «לא ברור».
# המספר שאחרי הסמן («אולי/אפשר/מה עם/can we do/what about/make it», או «N instead») — לא הראשון בהודעה
# («3 תשלומים זה הרבה, אולי 6?» = 6). ב-PLAN_PENDING_OWNER זהירים יותר (ההסדר כבר אושר ע״י הלקוח):
# בלי ספרה לבד, בלי «ב-6» / «עד ה-6» (יכול להיות תאריך), 2–12 בלבד, ושונה מההסדר הנוכחי.
_CNT_EN_NUM = {"two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10,
           "eleven": 11, "twelve": 12}
_CNT_TAIL = (r"(?![\d\w]|\s*(?:₪|ש\"ח|שח|שקל|ימימ|יומ|לחודש|בחודש|באותו|ב?(?:ינואר|פברואר|מרצ|אפריל|מאי|יוני|יולי"
             r"|אוגוסט|ספטמבר|אוקטובר|נובמבר|דצמבר)|[./:%]\d|%|nis|ils|days?|weeks?|st\b|nd\b|rd\b|th\b|of\s+the\s+month)"
             # critic סבב 130: «can we do two fifty a month?» = 250 לחודש, לא «2 תשלומים» (הצעה של 600 ₪ ללקוח שאמר 250)
             r"|[\s-]+(?:twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)\b)")
_CNT_HE = (r"(?:^|[\s,.;!?(])(?:אולי|אפשר|ואמ|ומה אמ|מה עמ|מה לגבי|ואולי)\s+(?:בעצמ\s+|רק\s+|גמ\s+)?(?P<pre>(?:ב|ל)-?\s*)?"
           r"(?P<n>\d{1,2}|" + _NUMW + r")(?:\s*(?:תשלומימ|תשלומי|חלקימ|פעמימ|פעימות))?" + _CNT_TAIL)
_EN_NW = "|".join(_CNT_EN_NUM)
_CNT_EN = (r"\b(?:(?:can|could)\s+(?:we|i)\s+(?:do|make\s+it|have\s+it\s+in|go\s+with|split\s+it\s+(?:in|into)|pay\s+(?:it\s+)?in)"
           r"|what\s+about|how\s+about|make\s+it|maybe)\s+(?P<pre>in\s+)?(?P<n>\d{1,2}|" + _EN_NW + r")"
           r"(?:\s+(?:payments|installments|instalments|months))?" + _CNT_TAIL +
           r"|(?<![\w])(?P<n2>\d{1,2}|" + _EN_NW + r")\s+(?:(?:payments|installments|instalments|months)\s+)?instead\b")


def plan_counter(t: str, current: int = 0, pending: bool = False) -> int | None:
    """הצעה נגדית במספר תשלומים בתוך הסדר שבשיחה ⇒ המספר, או None. ההקשר (יש הסדר) נבדק אצל הקורא."""
    for rx in (_CNT_HE, _CNT_EN):
        for m in _c(rx).finditer(t):
            g = m.groupdict().get("n") or m.groupdict().get("n2") or ""
            n = int(g) if g.isdigit() else (_NUM_WORDS.get(g) or _CNT_EN_NUM.get(g) or 0)
            if pending and (m.groupdict().get("pre") and rx is _CNT_HE or not 2 <= n <= 12 or n == current):
                continue
            if 1 <= n <= 36:
                return n
    return None


# מנהל 268 («הבא» AI מ-267): הצעה נגדית בסכום החודשי אחרי שהלקוח אישר הסדר (PLAN_PENDING_OWNER) או באמצע הצעה —
# «300 בחודש זה הרבה, אולי 200?», «can we do 200 a month instead?», «what about 150 per month?». היה:
#  · PENDING «300 בחודש זה הרבה, אולי 200?» ⇒ הצעה *זהה* (4×300 — הסכום הראשון בהודעה = ההסדר הקיים), «ביקש/ה פריסה»
#    בלי שבעל העסק יודע שזה שינוי בהסדר שכבר אושר; «can we do 200 a month?» ⇒ «לא ברור».
#  · AWAITING «אולי 200 בחודש?» ⇒ «ביקש/ה 20 תשלומים ⚠️ מעל התקרה» (ספרה לבד נקראה מתוך 200).
# הסכום שאחרי הסמן («אולי / אפשר / מה עם / can we do / what about / how about / maybe»), רק כשיש עוגן חודשי
# בהודעה (בחודש / לחודש / a month / monthly — ליד הסכום החדש או ליד הישן) ⇒ אחרת «אולי 300?» יכול להיות תשלום חד-פעמי.
_CTR_AMT = r"(?:₪|\$|nis\s*|ils\s*)?(?P<a>\d{1,3}(?:,\d{3})+|\d{2,5})(?![\d.,/:])"
_CTR_HE = (r"(?:^|[\s,.;!?(])(?:אולי|אפשר|ואמ|ומה אמ|מה עמ|מה לגבי|ואולי)\s+(?:בעצמ\s+|רק\s+|גמ\s+)?(?:לשלמ\s+)?(?:ב|ל)?-?\s*"
           + _CTR_AMT)
_CTR_EN = (r"\b(?:(?:can|could)\s+(?:we|i)\s+(?:do|make\s+it|pay|go\s+with)|what\s+about|how\s+about|make\s+it|maybe)\s+"
           r"(?:just\s+|only\s+)?" + _CTR_AMT)
_CTR_EN2 = (r"(?<![\w$₪])" + _CTR_AMT + r"\s*(?:₪|nis|ils|shekels?)?\s*(?:(?:a|per)\s+month\s+|monthly\s+)instead\b")
_MONTH_ANCHOR = (r"(?:כל חודש|לחודש|בחודש(?! ה)|חודשי|\b(?:a|per|each|every)\s+month\b|/\s*(?:month|mo)\b|\bmonthly\b)")


def _plan_monthly(ctx: Context | None) -> int:
    """התשלום החודשי בהסדר שבשיחה (הגדול מבין התשלומים; 0 אם אין)."""
    return max((i.amount_agorot for i in ctx.offered_plan), default=0) if ctx is not None and ctx.offered_plan else 0


def plan_counter_amount(t: str, current: int = 0) -> int | None:
    """הצעה נגדית בסכום חודשי בתוך הסדר שבשיחה ⇒ אגורות, או None. `current` = התשלום החודשי בהסדר (אגורות)."""
    if not _s(_MONTH_ANCHOR, t):
        return None
    for rx in (_CTR_HE, _CTR_EN, _CTR_EN2):
        for m in _c(rx).finditer(t):
            after = t[m.end():m.end() + 14]
            # «אולי 6 תשלומים» / «אולי 200 ימים» / «maybe 20 days» — לא סכום
            if _m(r"\s*(?:תשלומ|פעמימ|פעימות|ימימ|יומ|שבוע|חודשימ|payments|installments|instalments|days?|weeks?|months\b)",
                  after):
                continue
            v = int(m.group("a").replace(",", ""))
            if not 10 <= v <= 1_000_000:
                continue
            # עד 2 ספרות בלי מטבע מפורש = מספר תשלומים או יום בחודש («אפשר ב-20 לחודש?» = תאריך)
            if v < 100 and not (_m(r"\s*(?:₪|ש\"ח|שח|שקל|nis|ils)", after) or _s(r"[₪$]|nis|ils", m.group(0))):
                continue
            if v * 100 == current:
                continue
            return v * 100
    return None


def plan_retract(t: str) -> bool:
    """הלקוח חוזר בו מההסדר — בלי בקשה חדשה וממשית (מספר תשלומים / סכום חודשי / שינוי מועד)."""
    return bool(_s(_RETRACT, t)) and not _s(_RETRACT_NEG, t) and extract_installments(t) is None and \
        extract_monthly_amount(t) is None and plan_change(t) is None and plan_counter(t) is None and \
        plan_counter_amount(t) is None


def change_date(t: str, today: date) -> date | None:
    """המועד החדש שמבוקש — אחרי הסרת החלופה שנדחית («לא ל-10»)."""
    u = _c(_CHG_NOT).sub(" ", t)
    d, vague = extract_date_ctx(u, Context(today=today, business="", state=State.PROMISED))
    if d is not None and not vague:
        return d
    m = _s(r"(?<![\w])(?:ה)?(?:ב|ל|עד)-?\s*(?:ה-?)?(\d{1,2})(?![\d\w./])|\b(?:on|to)\s+(?:the\s+)?(\d{1,2})(?:st|nd|rd|th)?\b", u)
    if m:
        day = int(m.group(1) or m.group(2))
        if 1 <= day <= 31:
            return _month_day(today, day)
    return None


def plan_change_amount(t: str) -> int | None:
    """סכום חודשי חדש: «להוריד את התשלום החודשי ל-200», «lower the monthly payment to 200»."""
    a = extract_monthly_amount(t)
    if a:
        return a
    m = _s(r"(?:ל|to)\s*-?\s*(\d{1,3}(?:,\d{3})+|\d{2,})\s*(?:₪|ש\"ח|שח|שקל\w*|nis|ils)?(?![\d\w])", _c(_CHG_NOT).sub(" ", t))
    if m:
        v = int(m.group(1).replace(",", ""))
        return v * 100 if 10 <= v <= 1_000_000 else None
    return None


def extract_date_ctx(t: str, ctx: Context | None) -> tuple[date | None, bool]:
    """extract_date + יום בחודש לבד כשההקשר הוא תשובה ל«עד מתי?» (או עדכון מועד אחרי הבטחה)."""
    if ctx is None:
        return None, False
    t = _promise_prep(t)   # מנהל 263
    # מנהל 261 (q13-11): «אשלםב20» — פועל הבטחה צמוד למילת היחס והיום (בלי רווח) ⇒ מפרידים
    t = re.sub(_c(r"(?<![\w])(אשלמ|נשלמ|אעביר|נעביר|אסדר|נסדר|אפקיד|נפקיד)(ב|עד)(?=-?\d)"), r"\1 \2", t)
    # מנהל 261 (q13-13): «אני משלמת ב-20» (הווה + יום מיד אחריו) = «אשלם ב-20». «אני משלמת כל חודש ב-10» ⇒ לא נוגע.
    t = re.sub(_c(r"(?<![\w])(?:אני|אנחנו) (?:משלמ|משלמת|משלמימ|מעביר|מעבירה|מעבירימ)"
                  r"(?: (?:לכמ|את זה|את הכל|את הכול|את החוב))?(?= (?:ב|עד)\s*-?\s*(?:ה)?\d)"), "אשלמ", t)
    pc = _promise_clause_date(t, ctx.today)   # מנהל 260: תאריך של משפט ההבטחה גובר
    if pc is not None:
        return pc, False
    d, vague = extract_date(t, ctx.today)
    if d is None and ctx.state in (State.AWAITING_DATE, State.PROMISED):
        # מנהל 260 (q12-16): «שלישי הבא» / «יום חמישי» לבד כתשובה ל«עד מתי?» (בלי «ב»/«ביום»)
        wm = _fm(r"\W*(?:יום\s+)?(ראשון|שני|שלישי|רביעי|חמישי|שישי)(?:\s+(?:ה)?(הבא|הקרוב))?\W*", t)
        if wm:
            return _next_weekday_he(ctx.today, _WEEKDAYS[wm.group(1)], wm.group(2) or "")
        bd = _bare_day(t, ctx.today, need_marker=ctx.state == State.PROMISED)
        if bd is not None:
            return bd, False
    if d is None:
        bd = _promise_clause_day(t, ctx.today)
        if bd is not None:
            return bd, False
    if d is None:
        bd = _owner_correction_day(t, ctx)
        if bd is not None:
            return bd, False
    if d is None and not vague and ctx.state == State.IDLE:
        do = _date_only(t, ctx.today)   # מנהל 263: הודעה ראשונה שהיא רק מועד (ב-AWAITING_OWNER — רק תיקון מפורש, 257)
        if do is not None:
            return do
    return d, vague


# מנהל 257 (qa10 q10-07 #4): «ב-23» (מעל max_defer_days ⇒ AWAITING_OWNER), «תודה», ואז «בעצם ב-25» ⇒ אין מועד:
# יום לבד נתפס רק ב-AWAITING_DATE/PROMISED. ב-AWAITING_OWNER המצב משותף לכל ההעברות (מחלוקת, מצוקה, לא ברור…),
# לכן כאן רק **תיקון מפורש**: מילת תיקון בראש ההודעה («בעצם», «תיקון», «רגע», «סליחה», «actually», «sorry») +
# יום עם מילת יחס, וכל ההודעה היא התאריך. «ב-25» לבד, «17», «שילמתי ב-25» ⇒ לא נתפס.
_CORRECTION_LEAD = (r"^\W*(?:(?:אז|אה|אהה|טוב|אוקיי|אוקי|לא)\W+)?(?:בעצם|תיקון|רגע|סליחה|טעיתי|התכוונתי|כלומר|זאת אומרת|כוונתי|הכוונה|יעני)(?![\w])"
                    r"|^\W*(?:(?:oh|ok|okay|no)\W+)?(?:actually|sorry|correction|i\s+meant)\b"
                    # מנהל 258 (qa11 q11-16/19/21): ויתור/הקדמה אחרי מועד רחוק — «טוב אני יכולה להקדים, ב-20»,
                    # «אם זה בעיה אז ב-19 לחודש הזה», «אוקיי אוקיי, ב-13». עדיין חובה מילה מובילה + יום עם מילת יחס;
                    # «ב-25» לבד (rm257-03) ⇒ לא נתפס.
                    r"|^\W*(?:טוב|אוקיי|אוקי|בסדר|סבבה|יאללה)(?![\w])"
                    # מנהל 260 (q12-25): «אם זה מסבך אותכם אני יכולה גם ב-20 לחודש הזה»
                    r"|^\W*(?:אמ (?:זה|זאת) (?:\w+\W+){0,3}?)?(?:אני |אנחנו )?(?:יכול|יכולה|יכולימ|אוכל|נוכל) (?:גמ )?(?=(?:ב|עד)\s*-?\s*(?:ה)?\d)"
                    r"|^\W*(?:(?:טוב|אוקיי|אוקי|אז)\W+)?(?:אמ (?:זה|זאת) (?:\w+\W+){0,2}?אז|(?:אני |אנחנו )?(?:יכול|יכולה|יכולימ|אוכל|נוכל) להקדימ|אקדימ|נקדימ)(?![\w])")
_CORRECTION_STRIP = (r"^\W*(?:אמ (?:זה|זאת) (?:\w+\W+){0,3}?(?=(?:אני |אנחנו )?(?:יכול|יכולה|יכולימ|אוכל|נוכל) )"
                     r"|(?:אני |אנחנו )?(?:יכול|יכולה|יכולימ|אוכל|נוכל) (?:גמ )?(?=(?:ב|עד)\s*-?\s*(?:ה)?\d)|(?:אז|אה|אהה|טוב|אוקיי|אוקי|לא|בסדר|סבבה|יאללה|כנ|בעצמ|תיקונ|רגע|סליחה|טעיתי|התכוונתי|כלומר|זאת אומרת|כוונתי|הכוונה|יעני|אקדימ|נקדימ)(?![\w])\W*"
                     r"|אמ (?:זה|זאת) (?:\w+\W+){0,2}?אז(?![\w])\W*|(?:אני |אנחנו )?(?:יכול|יכולה|יכולימ|אוכל|נוכל) להקדימ(?![\w])\W*)*")


def _owner_correction_day(t: str, ctx: Context) -> date | None:
    if ctx.state != State.AWAITING_OWNER or not re.search(_c(_CORRECTION_LEAD), t):
        return None
    u = re.sub(_c(_CORRECTION_STRIP), "", t)
    u = re.sub(r"^\W*(?:(?:oh|ok|okay|no)\W+)?(?:(?:actually|sorry|correction|i\s+meant)\b\W*)+", "", u)
    bd = _bare_day(u, ctx.today, need_marker=True)
    if bd is None and u != t:
        # מנהל 258 (q11-17/21): «Sorry, I meant November 15, not December», «טוב, אז בחודש הבא» — תאריך מלא אחרי מילת התיקון
        u2 = re.sub(r",?\s*(?:not|rather\s+than)\s+(?:in\s+|on\s+)?[a-z]+\W*$", "", u)
        u2 = re.sub(_c(r",?\s*(?:ולא|לא)\s+(?:ב)?\S+\W*$"), "", u2)
        d, vague = extract_date(u2, ctx.today)
        if d is not None and not vague and d > ctx.today and not re.search(_c(r"\d\s*(?:תשלומ|payments|installments)"), u2):
            bd = d
    return bd


# מנהל 256 (qa10 q10-02/14/19/23/27): «קיבלתי תודה. אשלם ב-15», «סליחה, לא הספקתי. אשלם ב-20»,
# «לא, זה לא מתאים לי. אשלם הכל ב-20» ⇒ אין תאריך: יום בחודש לבד נתפס רק כשכל ההודעה היא התאריך,
# ורק ב-AWAITING_DATE/PROMISED. כאן: משפט אחד בהודעה (מופרד בנקודה/פסיק/סימן) שהוא *פועל הבטחה* + מילת
# יחס + יום, ובכל מצב. בלי פועל הבטחה («תתקשרו ב-5», «שילמתי 17», «ב-3 תשלומים») ⇒ לא נתפס.
_PROMISE_VERB_HE = (r"(?:אשלם|נשלם|אעביר|נעביר|אסדר|נסדר|אסדיר|נסדיר|אפקיד|נפקיד"
                    # מנהל 260 (q12-10/17): «אז אוכל לשלם לכם ב-11», «אני אסגור את זה ביום שישי»
                    r"|(?:אוכל|נוכל|אני יכול\w*|אנחנו יכולים) (?:לשלם|להעביר|לסדר|לסגור)"
                    r"|(?:אסגור|נסגור) (?:את )?(?:זה|החוב|החשבון|הכל|הכול|העניין|התשלום|היתרה))(?![\w])")
# מנהל 260 (q12-27): «הן עוזרות לי לזכור :) אשלם ב-16» — סמיילי מפריד משפטים
_CLAUSE_SPLIT = r"(?:[.!?;\n]|,(?!\d)|[:;]-?[()](?![\w])|[\u2600-\u27BF\U0001F300-\U0001FAFF])+"
_PROMISE_VERB_EN = r"(?:i'?ll|i\s+will|we'?ll|we\s+will|i\s+can|can\s+i)\s+(?:pay|transfer|settle)"


def _promise_clause_day(t: str, today: date) -> date | None:
    for clause in re.split(_CLAUSE_SPLIT, t):
        c = clause.strip()
        if not c:
            continue
        he = re.search(_c(_PROMISE_VERB_HE), c)
        en = re.search(_PROMISE_VERB_EN, c) if re.search(r"[a-z]", c) else None
        if not (he or en):
            continue
        bd = _bare_day(c, today, need_marker=True)
        if bd is not None:
            return bd
    return None



# מנהל 260 (q12-10/21 — טעויות בטוחות-בעצמן): «המספר שלי יהיה כבוי מחר כל היום, אז אשלם ביום שלישי» ⇒ נרשם «מחר»;
# «התשלומים של האשראי יורדים לי ב-10 לחודש, אז אוכל לשלם לכם ב-11» ⇒ נרשם 10. התאריך הראשון בהודעה ניצח גם כשהוא
# שייך למשפט אחר. כאן: התאריך שאחרי פועל ההבטחה, במשפט של הפועל. min_clauses=2 ⇒ רק כשיש כמה משפטים (אחרת ביט-זהה).
_AFTER_VERB_FILL = r"^\W*(?:(?:לכם|לכן|לך|את זה|את הכל|את הכול|הכל|הכול|את החוב|את היתרה|את הסכום|את התשלום|כבר|רק|גם)\W+)*"


def _promise_clause_date(t: str, today: date, min_clauses: int = 2) -> date | None:
    clauses = [c.strip() for c in re.split(_CLAUSE_SPLIT, t) if c.strip()]
    if len(clauses) < min_clauses:
        return None
    for c in clauses:
        m = re.search(_c(_PROMISE_VERB_HE), c)
        if m is None and re.search(r"[a-z]", c):
            m = re.search(_PROMISE_VERB_EN, c)
        if m is None:
            continue
        u = re.sub(_c(_AFTER_VERB_FILL), "", c[m.end():])
        if not u.strip() or re.search(_c(r"\d\s*(?:תשלומ|payments|installments)"), u):
            continue
        d, vague = extract_date(u, today)
        if d is not None and not vague and d >= today:
            return d
        bd = _bare_day(u, today, need_marker=True)
        if bd is not None:
            return bd
    return None

# ═══════════════════════════ סיווג ═══════════════════════════
# critic סבב 79–80: סמני הגנה משותפים. כל חוק discard שמוריד dispute/legal מכבד אותם — אחרת כל חוק חדש מגיע עם
# רשימת חריגים צרה משלו ומפיל בביטחון «לא חייב», «זה לא שלי» או «תפנו לעו"ד שלי» (סבב 4: 4 רגרסיות, סבב 5: 4).
_KEEPS_DISPUTE = (r"לא הזמנתי|סכום|מחיר|סיכמנו|עבודה|שירות|חיוב|כפול|תתקנו|תסדרו|לא מגיע"
                  r"|לא (?:חייב|חייבת|חייבים|שלי|שלנו)(?!\w)|(?:החוב|החשבונית) (?:הזה|הזאת|הזו )?לא")
_KEEPS_LEGAL = (r"תביע|אתבע|לתבוע|נתבע|משטרה|בית ה?משפט|תלונה|אגיש|ייצור\w* קשר|יפנה|תפנה|מכתב|הליך"
                r"|(?:אפנה|נפנה|תפנו|פנו|תדברו|דברו|ידבר|שידבר|תתקשרו|יתקשר|שיתקשר)\w* (?:אליו|אליה|איתו|איתה|אליכם"
                r"|לעורך|לעו|עם (?:ה)?(?:עורך|עו))|דרך (?:ה)?(?:עורך|עו\"ד)|מייצג|ייצוג"
                r"|(?:גם )?(?:לי|לנו) יש (?:עורך|עו\"ד)|(?:אחרי|לאחר) ש(?:הוא|היא)? ?(?:י|ת)?(?:בדוק|בדק|עבור|עבר)"
                r"|\bcourt\b|\bsue\b|\blawsuit|\bsmall claims|\bcomplaint|\bhandling (?:it|this)|\bbe in touch|\bcontact (?:him|her|them|my)|\brepresent")


# כוונות מגינות — כשהן בהודעה, לא מוסיפים פרשנות של הצעה נגדית (מנהל 267)
_PROTECTIVE = frozenset({Intent.DISTRESS, Intent.MINOR, Intent.OPT_OUT, Intent.WRONG_PERSON, Intent.LEGAL,
                         Intent.DISPUTE, Intent.PAID_CLAIM})


def _plan_ctx(ctx: Context | None) -> bool:
    """יש הסדר בשיחה (הוצע ללקוח, או שהלקוח אישר/בעל העסק אישר) ⇒ בקשות שינוי מתפרשות מולו."""
    return ctx is not None and bool(ctx.offered_plan) and \
        ctx.state in (State.AWAITING_PLAN_REPLY, State.PLAN_PENDING_OWNER)


def detect(text: str, ctx: Context | None = None) -> list[Intent]:
    """כל הכוונות שזוהו, לפי סדר העדיפות."""
    t = normalize(text)
    if not t:
        return [Intent.UNKNOWN]
    found: set[Intent] = set()
    t_plan = _GEN_PAYMENTS.sub(" ", t)   # מנהל 260: «התשלומים» כשם עצם כללי
    for it, rx in RX.items():
        if it in STATEFUL:
            continue
        if _hits(rx, t_plan if it == Intent.PLAN_REQUEST else t, negatable=it in NEGATABLE):
            found.add(it)
    t_dg = _deglue(_typofix(t))   # מנהל 262: הדבקת מילים · 263: שגיאות כתיב — רק כוונות מגינות
    if t_dg != t:
        for it in _GLUE_INTENTS:
            if it not in found and _hits(RX[it], t_dg, negatable=it in NEGATABLE):
                found.add(it)
    awaiting = ctx is not None and ctx.state == State.AWAITING_PLAN_REPLY
    if awaiting:
        if _hits(RX[Intent.PLAN_REJECT], t):
            found.add(Intent.PLAN_REJECT)
        elif _hits(RX[Intent.PLAN_ACCEPT], t):
            found.add(Intent.PLAN_ACCEPT)
        elif _hits(RX[Intent.PLAN_ACCEPT], re.sub(r"^\W*(?:תודה(?:\s+רבה)?|thanks|thank\s+you|thx)\W+", "", t, flags=re.I)):
            # מנהל 269 (qa15 q15-29): «תודה מתאים» / «thanks, ok» על הצעה פתוחה ⇒ היה «תודה» וההצעה נשארה פתוחה
            found.add(Intent.PLAN_ACCEPT)
            found.discard(Intent.THANKS)
        # ספרה לבד או "ב-4" ⇒ הצעה נגדית
        # מנהל 269 (qa15 q15-08/30): «טוב אז שישה», «ok six», «ok then 6 payments» ⇒ היה «לא ברור» / אישור ההצעה הקודמת
        if _fm(r"\W*(?:(?:טוב|אוקי|אוקיי|ok|okay|בסדר|סבבה|יאללה)\W+)?(?:אז\s+|then\s+|so\s+)?(?:אפשר |ו?אם |מה עם )?"
               r"(?:ב-?|ל-?)?(\d{1,2}|" + _NUMW + r"|" + _EN_INW + r")\W*\??", t) or \
                _s(r"(?:אפשר|ואם|מה עם|רק|אולי) (?:ב-?|ל-?)?(\d{1,2}|" + _NUMW + r")(?![\d\w])", t):
            found.add(Intent.PLAN_REQUEST)
        # critic סבב 130: «can we do two fifty a month?» (= 250 לחודש) — «two» לפני מילת עשרות אינו מספר תשלומים
        if re.search(r"\b(?:can|could)\s+(?:we|i)\s+(?:do|make\s+it|have\s+it\s+in|go\s+with|split\s+it\s+(?:in|into))\s+"
                     r"(?:\d{1,2}|two|three|four|five|six|eight|ten|twelve)\b"
                     r"(?![\s-]+(?:twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)\b)|\bwhat\s+about\s+(?:\d{1,2}|two|three|four|five|six)\b"
                     r"|\b(?:\d{1,2}|two|three|four|five|six)\s+(?:payments|installments|months)\s+instead\b", t):
            found.add(Intent.PLAN_REQUEST)
    # מנהל 269 (qa15 q15-24/30): «ok then 6 payments» / «אוקי אז 6 תשלומים» כשהוצעו 3 = הצעה נגדית, לא אישור ההצעה
    # שנשלחה (היה: plan_accept ⇒ הלקוח «אישר» 3 תשלומים). אותו מספר כמו בהצעה ⇒ נשאר אישור.
    if awaiting and ctx.offered_plan and Intent.PLAN_REQUEST in found and (
            Intent.PLAN_ACCEPT in found or (_s(r"(?<![\w])(?:מאשר|מאשרת|מאשרימ|מסכימ|מסכימה|מסכימימ)(?![\w])"
                                               r"|\b(?:i\s+)?(?:accept|agree|confirm)\b", t)
                                            and not _hits(RX[Intent.PLAN_REJECT], t) and not _s(_RETRACT_NEG, t)
                                            and not _s(r"(?<![\w])(?:לא|אל)(?![\w])|\bnot\b|n'?t\b|\bno\b", t))):
        n_req = extract_installments(t)
        if n_req is None:
            mb = _fm(r"\W*(?:(?:טוב|אוקי|אוקיי|ok|okay|בסדר|סבבה|יאללה)\W+)?(?:אז\s+|then\s+|so\s+)?(?:ב-?|ל-?)?(\d{1,2}|"
                     + _NUMW + r"|" + _EN_INW + r")\W*\??", t)
            if mb:
                g = mb.group(1)
                n_req = int(g) if g.isdigit() else (_NUM_WORDS.get(g) or _EN_INST.get(g.lower()))
        if n_req is not None and n_req != len(ctx.offered_plan):
            found.discard(Intent.PLAN_ACCEPT)
        elif n_req == len(ctx.offered_plan) and extract_monthly_amount(t) is None and plan_change(t) is None \
                and not _s(r"(?<![\w])(?:לא|אל)(?![\w])|\bnot\b|n'?t\b|\bno\b", t):
            found.add(Intent.PLAN_ACCEPT)
            found.discard(Intent.PLAN_REQUEST)   # «סבבה מאשרת 3 תשלומים» על הצעה של 3 = אישור (היה: הסדר זהה חדש)
    # מנהל 265: אישור חוזר במצב PLAN_PENDING_OWNER («מאשרת» אחרי שכבר אישרה, או תשובה ל«השיבו מאשר» אחרי
    # שבעל העסק שלח את ההסדר). היה: «לא ברור» ⇒ כרטיס בלי הקשר. רק כשההודעה היא אישור בלבד (בלי כוונה אחרת);
    # «סגור, תודה רבה» נשאר «תודה» (q11-07, תווית עיוורת) — אותה התנהגות: בלי תשובה ובלי כרטיס.
    if ctx is not None and ctx.state == State.PLAN_PENDING_OWNER and ctx.offered_plan \
            and not (found - {Intent.THANKS, Intent.UNKNOWN}) \
            and ("?" in t or not _s(r"(?<![\w])(?:תודה|thanks|thank\s+you|thx|ty)(?![\w])", t)) \
            and not _hits(RX[Intent.PLAN_REJECT], t) and _hits(RX[Intent.PLAN_ACCEPT], t):
        found.add(Intent.PLAN_ACCEPT)
    # מנהל 267: הצעה נגדית במספר תשלומים («אולי 6?», «can we do 6 instead?») — גם אחרי שהלקוח אישר.
    # גוברת על «לא מסתדר / too much» (שאחרת נקראים דחייה/חזרה מההסדר) ועל אישור/«לא ברור».
    if _plan_ctx(ctx) and not (found & _PROTECTIVE) and plan_change(t) is None and (plan_counter(
            t, len(ctx.offered_plan), ctx.state == State.PLAN_PENDING_OWNER) is not None
            or plan_counter_amount(t, _plan_monthly(ctx)) is not None):   # מנהל 268: גם סכום חודשי נגדי
        found.add(Intent.PLAN_REQUEST)
        found -= {Intent.PROMISE, Intent.UNKNOWN, Intent.PLAN_ACCEPT, Intent.THANKS}
        # ב-AWAITING_PLAN_REPLY דחייה+מספר נשארת «דחייה עם הצעה נגדית» (תווית f034, סט קפוא); ההצעה תהיה במספר
        # הנגדי. ב-PLAN_PENDING_OWNER דחייה = «חוזר/ת בו» ⇒ חייבים להסיר, אחרת הבקשה הממשית (6) אובדת.
        if ctx.state == State.PLAN_PENDING_OWNER:
            found.discard(Intent.PLAN_REJECT)
    # מנהל 264: בקשת שינוי בהסדר שבשיחה (מועד/סכום/מספר תשלומים) ⇒ פריסה, לא הבטחה/«לא ברור»/אישור/דחייה
    if _plan_ctx(ctx) and plan_change(t) is not None:
        found.add(Intent.PLAN_REQUEST)
        found -= {Intent.PROMISE, Intent.UNKNOWN, Intent.PLAN_ACCEPT, Intent.PLAN_REJECT, Intent.THANKS}
    # מנהל 266: חזרה מההסדר. היה: «אני מבטלת את ההסדר» / «חזרתי בי» ⇒ PLAN_REQUEST ⇒ הצעה *חדשה וזהה*
    # («בשמחה. הצעה לפריסה…») שנרשמה כהסדר proposed נוסף; «לא מתאים לי בסוף» ⇒ «לא ברור».
    # ב-AWAITING_PLAN_REPLY ⇒ דחיית ההצעה (המסלול הקיים). ב-PLAN_PENDING_OWNER ⇒ כרטיס עם הקשר, בלי ביטול אוטומטי.
    if _plan_ctx(ctx) and plan_retract(t):
        found.add(Intent.PLAN_REJECT)
        found -= {Intent.PLAN_REQUEST, Intent.PLAN_ACCEPT, Intent.UNKNOWN, Intent.THANKS}
    elif _plan_ctx(ctx) and _s(_RETRACT_NEG, t) and Intent.PLAN_REQUEST in found and plan_change(t) is None \
            and extract_installments(t) is None and extract_monthly_amount(t) is None:
        # «אל תבטלו את ההסדר» — היה: «הסדר» ⇒ PLAN_REQUEST ⇒ הצעה חדשה וזהה. אין כאן בקשה ⇒ כרטיס רגיל.
        found.discard(Intent.PLAN_REQUEST)
        if not found:
            found.add(Intent.UNKNOWN)
    elif ctx is not None and ctx.state == State.PLAN_PENDING_OWNER and ctx.offered_plan \
            and not (found - {Intent.UNKNOWN}) and _hits(RX[Intent.PLAN_REJECT], t) and not _s(_RETRACT_NEG, t) \
            and not _s(r"^\W*לא\s+(?!(?:מתאים|מתאימה|מסתדר|מסתדרת|טוב|מסכים|מסכימה|ממש|זה)(?![\w]))", t):
        # «לא בסמס, רק במייל», «לא שילמתי עדיין», «לא מעביר מחר», «לא תודה» ⇒ לא דחיית ההסדר (נשארים כקודם)
        found.add(Intent.PLAN_REJECT)       # «לא» / «לא מתאים לי» לבד אחרי האישור ⇒ כרטיס עם הקשר
        found.discard(Intent.UNKNOWN)
    # מנהל 251 (qa8): «I'm not Dana», «this isn't Dana», «no Dana here» — שם באותיות לטיניות (שם הלקוח במערכת בעברית).
    # שם פרטי = מילה באות גדולה בטקסט המקורי, לא מילה מרשימת השגרה («I'm not Sure/Home» ≠ טעות במספר).
    _m_name = re.search(r"\b(?:I'?m|I\s+am|Im|i'?m|i\s+am|im|[Tt]his\s+is\s*n'?t|[Tt]his\s+is\s+not|[Ii]t'?s\s+not|[Mm]y\s+name\s+is\s*n'?t"
                        r"|[Mm]y\s+name\s+is\s+not)\s+(?:not\s+)?([A-Z][a-z]{1,15})\b(?!'|\s*-)"
                        r"|\b[Nn]o\s+([A-Z][a-z]{1,15})\s+(?:here|at\s+this\s+number)\b|\b[Tt]here'?s\s+no\s+([A-Z][a-z]{1,15})\b", text or "")
    if _m_name and (_m_name.group(1) or _m_name.group(2) or _m_name.group(3) or "") not in _EN_NOT_NAMES and \
            (_m_name.group(2) or _m_name.group(3) or re.search(r"\bnot\b|n'?t\b", _m_name.group(0))):
        found.add(Intent.WRONG_PERSON)
    # זיהוי לפי שם הלקוח מההקשר: "אין פה דנה" / "אני לא דנה" / "לא מכיר שום דנה"
    fn = normalize(ctx.first_name) if ctx is not None else ""
    if fn and len(fn) >= 2 and _s(r"(?:אין (?:פה|כאן|בבית|בטלפון הזה)|לא מכיר\w*|אני לא|זה לא|מי (?:זאת|זה|זו)|אין לי)"
                                  r"\W+(?:\w+\W+){0,2}" + re.escape(fn) + r"(?![\w])", t):
        found.add(Intent.WRONG_PERSON)
    if fn and len(fn) >= 2 and _s(r"(?<![\w])לא\W+" + re.escape(fn) + r"\W+(?:פה|כאן|בבית|גר|גרה)(?![\w])", t):
        found.add(Intent.WRONG_PERSON)
    # שאלה על תשלום ("מתי שילמתי?") ≠ טענת תשלום
    if Intent.PAID_CLAIM in found and _s(r"^\W*(?:מתי|האם|כמה|למה|איך|מה)\b[^.!]*\?\W*$", t) \
            and not _s(r"(?:כבר )?(?:שילמתי|העברתי|שילמנו|העברנו)[^?]*[.!,]", t):
        found.discard(Intent.PAID_CLAIM)
    # הבטחה בזמן הווה עם תאריך: "תוך שבוע אני מסדר"
    # מנהל 248 (qa6 x6-41): «רק עכשיו ראיתי. איך משלמים?» — הפועל בתוך שאלת «איך/לאן» אינו הבטחה
    _t_noq = re.sub(_c(r"(?:איך|לאן|למי|איפה|כמה|באיזה \w+|באיזו \w+)\s+(?:\w+\s+){0,2}?(?:משלמ|מעביר|מפקיד|מסדר)\w*"), " ", t)
    if ctx is not None and Intent.PROMISE not in found and \
            _hits(_c(_ws("מסדר", "מעביר", "משלמ", "מטפל", "מפקיד", "סוגר")), _t_noq, negatable=True) and \
            (extract_date(t, ctx.today)[0] or _s(r"(?:עכשיו|כרגע|מיד|תיכף|בדקות הקרובות)", t)) and \
            not _s(r"(?:משלמ|מעביר|מפקיד)\w*\s+(?:\w+\s+){0,2}?(?:כל|בכל)\s+(?:חודש|שבוע)", t):
        # מנהל 261: «אני משלמת כל חודש ב-10 את המשכנתא, אין לי כסף לזה עכשיו» = הרגל, לא הבטחה (היה promise משני)
        found.add(Intent.PROMISE)
    # מנהל 260 (q12-17): «אני אסגור את זה ביום שישי בבוקר», «אוכל לשלם לכם ב-11» — פועל הבטחה (לא מוכחש) + מועד במשפט שלו
    if ctx is not None and Intent.PROMISE not in found and _hits(_c(_PROMISE_VERB_HE), t, negatable=True) and \
            _promise_clause_date(t, ctx.today, min_clauses=1) is not None:
        found.add(Intent.PROMISE)
    # מנהל 263 (q14-15/22/24/25): «ב20 אני משלמת», «אנימשלמת», «אשלם בביט ב-19», «אשלם שני הבא»
    t_pp = _promise_prep(t)
    if ctx is not None and Intent.PROMISE not in found and t_pp != t and (
            _hits(RX[Intent.PROMISE], t_pp, negatable=True) or
            (_hits(_c(_PROMISE_VERB_HE), t_pp, negatable=True) and _promise_clause_date(t_pp, ctx.today, min_clauses=1))
            or (_hits(_c(_ws("מעביר", "משלמ")), t_pp, negatable=True) and extract_date(t_pp, ctx.today)[0] is not None
                and not _s(r"(?:משלמ|מעביר)\w*\s+(?:\w+\s+){0,2}?(?:כל|בכל)\s+(?:חודש|שבוע)", t_pp))):
        found.add(Intent.PROMISE)
    # מנהל 263: הודעה ראשונה שהיא רק מועד («חמישי הבא», «ב-15», «אחרי המשכורת, ב-1 לדצמבר») ⇒ הבטחה
    if ctx is not None and not found and ctx.state == State.IDLE and _date_only(t, ctx.today) is not None:
        found.add(Intent.PROMISE)
    if ctx is not None and ctx.state in (State.AWAITING_DATE, State.PROMISED):
        # מנהל 253 (qa9 q9-26): «בשבוע הבא» ⇒ PROMISED, ואז «ביום שלישי ה-17 בנובמבר» (דיוק המועד) ⇒ «לא ברור».
        # במצב PROMISED תאריך לבד = עדכון המועד. מעורפל לבד (חג) במצב AWAITING_DATE ⇒ הבטחה מעורפלת ⇒ שואלים שוב.
        d, _vague = extract_date_ctx(t, ctx)
        # מנהל 262: «שלישי הבא» / «next Tuesday» כשהיום הזה עוד לפנינו השבוע ⇒ מעורפל ⇒ שואלים שוב (לא «לא ברור»)
        if d is not None or (_vague and ctx.state == State.AWAITING_DATE and (
                _s(_HOLIDAY_VAGUE, t) or _s(_NEXT_WD_VAGUE, t) or re.search(_NEXT_WD_VAGUE_EN, t))):
            found.add(Intent.PROMISE)
    if ctx is not None and ctx.state == State.AWAITING_OWNER and _owner_correction_day(t, ctx) is not None:
        found.add(Intent.PROMISE)   # מנהל 257: «בעצם ב-25» אחרי מועד שהועבר לבעלים = עדכון המועד
    # מנהל 253 (qa9 q9-28/משלים): «אפשר לשלם ב-18 בנובמבר?», «Can I pay next week?» = בקשת דחייה עם מועד, לא «איך משלמים»
    if ctx is not None and (_s(r"(?:אפשר|אוכל|אני יכול\w*|ניתן|מותר)\s+(?:ל)?(?:שלם|לשלם|להעביר|לסדר|לדחות)", t)
                            or re.search(r"\b(?:can|could|may)\s+(?:i|we)\s+(?:pay|transfer|send\s+(?:it|the\s+payment)|settle)\b", t)
                            # מנהל 258 (qa11 q11-17): «I can pay on December 15» (חיווי, לא שאלה) — כמו «אני יכולה לשלם ב-…»
                            or re.search(r"\b(?:i|we)\s+(?:can|could)\s+(?:only\s+)?(?:pay|transfer|settle)\b", t)):
        d, _vague = extract_date(t, ctx.today)
        if (d is not None and d > ctx.today) or (_vague and re.search(r"[a-z]", t)) or _s(_HOLIDAY_VAGUE, t):
            if not _s(r"(?:איך|לאן|למי|איפה|באיזה|באיזו|בכרטיס|באשראי|בביט|בפייבוקס|בהעברה|בצ'?ק|במזומן)", t) and \
                    not re.search(r"\b(?:how|where|by\s+(?:card|credit|bit|paypal|check|cheque|bank|transfer)|with\s+(?:a\s+)?card|online|link)\b", t):
                found.add(Intent.PROMISE)
                found.discard(Intent.HOW_TO_PAY)
    # מנהל 242 (self4): «לא מכיר את המספר הזה, זה ממי?» = שאלה על השולח, לא «טעות במספר». בלי שם/«אין פה»/«טעות»
    # ⇒ who_is_this (תשובה עם שם העסק). רצפת ההגנה ב-respond עדיין משהה ומעלה כרטיס, כי wrong_person נתפס גולמית.
    if Intent.WRONG_PERSON in found and Intent.WHO_IS_THIS in found and \
            _s(r"לא (?:מכיר|מכירה|מזהה|מזהים|מכירים) (?:את )?(?:ה)?(?:מספר|שולח|טלפון)", t) and \
            not _s(r"טעות|בטעות|אין (?:פה|כאן)|זה לא אני|לא (?:ה)?לקוח|לא שלי|החלפתי|לא שייך", t) and \
            not (fn and len(fn) >= 2 and _s(re.escape(fn), t)):
        found.discard(Intent.WRONG_PERSON)
    # תיקוני התנגשות ידועים
    if Intent.PAID_CLAIM in found and _s(r"(?:איך|לאן|למי) (?:אפשר )?(?:לשלם|להעביר)", t) \
            and not _s(r"שילמתי|העברתי", t):
        found.discard(Intent.PAID_CLAIM)
    if Intent.CANT_PAY in found and _s(r"אין (?:לי|לנו) בעיה", t):
        found.discard(Intent.CANT_PAY)
    # "לא שלי" עם טענה נגד החוב, בלי סימני מספר/כתובת שגויים ⇒ מחלוקת (שומרת את החוב ומסלימה בדחיפות)
    if Intent.WRONG_PERSON in found and Intent.DISPUTE in found and not _s(
            r"מספר|מס'|כתובת|מייל|בטעות|לא מכיר|לא מכירה|אין (?:פה|כאן)|טלפון", t):
        found.discard(Intent.WRONG_PERSON)
    # critic סבב 121: «אני לא מכיר את החוב הזה» = מחלוקת על החוב, לא «לא מכיר את האדם» (היה חסימה לצמיתות)
    if Intent.WRONG_PERSON in found and Intent.DISPUTE in found and \
            _s(r"(?:לא|אינני)\s+(?:מכיר|מכירה|מכירים)\s+(?:את\s+)?(?:ה)?(?:חוב|חיוב|חשבונית|חשבון|סכום)(?![\w])", t) and not (
            _s(r"מספר|מס'|כתובת|מייל|בטעות|טעות|אין (?:פה|כאן)|טלפון|מישהו|מישהי|אחר|אחרת|שם", t)
            or (fn and len(fn) >= 2 and _s(r"(?<![\w])" + re.escape(fn) + r"(?![\w])", t))):
        found.discard(Intent.WRONG_PERSON)
    # ספק/שאלה על תשלום ("לא זוכר אם שילמתי", "האם התשלום התקבל?") ≠ טענת תשלום
    if Intent.PAID_CLAIM in found and (
            _s(r"(?:לא זוכר\w*|לא בטוח\w*|לבדוק|לברר|לוודא) (?:אם|האם|ש)", t)
            or _s(r"(?<![\w])(?:אם|האם) (?:כבר )?(?:שילמ|העבר|התשלום|הכסף)", t)) \
            and not _s(r"(?:^|[.!,\n] *)(?:כבר )?(?:שילמתי|שילמנו|העברתי|העברנו)(?![^.!?\n]*\?)", t):
        found.discard(Intent.PAID_CLAIM)
    # מנהל 249 (qa7 x7-42/45): «I haven't paid yet» / «not sure if I paid» ≠ טענת תשלום (אחרת: «תודה שעדכנתם» + השהיה)
    if Intent.PAID_CLAIM in found:
        t_en = re.sub(r"\b(?:have\s*n'?t|have\s+not|has\s*n'?t|has\s+not|had\s*n'?t|did\s*n'?t|did\s+not|not|never|"
                      r"if\s+(?:i|we)(?:'ve|\s+have|\s+already)?|whether\s+(?:i|we)(?:'ve|\s+have|\s+already)?|"
                      r"did\s+(?:i|we)|have\s+(?:i|we))\s+(?:yet\s+|already\s+|actually\s+)?(?:been\s+)?(?:paid|payed|transferred|wired|sent|deposited)\b(?:\s+(?:it|the\s+(?:money|payment|funds)))?(?:\s+yet)?", " ", t)
        if t_en != t and not _hits(RX[Intent.PAID_CLAIM], t_en):
            found.discard(Intent.PAID_CLAIM)
    if not found and "?" in t and _s(r"(?:ה)?(?:קישור|לינק)", t):
        found.add(Intent.HOW_TO_PAY)          # שאלה על הקישור לתשלום
    if not found and "?" not in t and _s(r"(?<![\w])(?:תודה|thanks)", t):
        found.add(Intent.THANKS)              # שבח + תודה בלי בקשה
    # "התשלום/ההעברה לא בוצע/ה" = תקלה בתשלום: לא טענה נגד החוב (critic סבב 80 🟡) וגם לא "שילמתי" ⇒ how_to_pay
    _failed_pay = r"(?:ה)?(?:תשלום|העברה|הפקדה|ביט|פייבוקס)\W+(?:\w+\W+){0,2}לא (?:בוצע|בוצעה|עבר|עברה|הצליח|הצליחה|נקלט|נקלטה)"
    # critic סבב 81: טענת תשלום מפורשת (גם כשאחריה «לא עבר») ⇒ נשאר paid_claim — אחרת ממשיכים לתזכר ושולחים קישור
    # למי שהכסף ירד לו (חשש לתשלום כפול). רק תקלה בלי טענה ⇒ how_to_pay
    _claims_paid = (r"(?<![\w])(?:כבר )?(?:שילמתי|שילמנו|העברתי|העברנו|הפקדתי|חויבתי|חויבנו)(?![\w])"
                    r"|ירד (?:לי |לנו )?(?:ה?כסף |הסכום )?מ?ה?(?:חשבון|כרטיס|אשראי)|(?:הכסף|הסכום) ירד")
    if Intent.PAID_CLAIM in found and _s(_failed_pay, t) and not _s(_claims_paid, t):
        found.discard(Intent.PAID_CLAIM)
        found.add(Intent.HOW_TO_PAY)
    if Intent.DISPUTE in found and _s(r"(?:ה)?(?:תשלום|העברה|הפקדה|ביט|פייבוקס)\W+(?:\w+\W+){0,2}לא (?:בוצע|בוצעה|עבר|עברה|הצליח|הצליחה|נקלט|נקלטה)", t) \
            and not _s(_KEEPS_DISPUTE, t):
        found.discard(Intent.DISPUTE)
        found.add(Intent.HOW_TO_PAY)
    # "הלינק לא עובד" = בעיה טכנית בקישור, לא מחלוקת על החוב
    if Intent.DISPUTE in found and _s(r"(?:קישור|לינק)\W+(?:\w+\W+){0,2}(?:לא )(?:עובד|נפתח|נטען)", t) \
            and not _s(_KEEPS_DISPUTE + r"|לא אשלם", t):  # critic סבב 79
        found.discard(Intent.DISPUTE)
        found.add(Intent.HOW_TO_PAY)
    # "זה לא אני ש… אבל אשלם" ⇒ מכיר בחוב: לא מספר שגוי (אחרת מסירים ומוחקים טלפון למשלם)
    if Intent.WRONG_PERSON in found and _s(_ws("אשלם", "נשלם", "אעביר", "נעביר", "אסדר", "נסדר", "אסדיר"), t) \
            and not _s(r"מספר|טלפון|בטעות|לא מכיר|רק אם|תוכיח|הוכח|לא אשלם", t):  # critic סבב 79: התניה ≠ הכרה
        found.discard(Intent.WRONG_PERSON)
    # עו"ד שממליץ לשלם / "דיברתי עם עו"ד" + כוונת תשלום, בלי מילות הליך ⇒ לא איום
    if Intent.LEGAL in found and (Intent.HOW_TO_PAY in found or Intent.PROMISE in found or _s(
            r"(?:אמר|אמרה|אמרו|המליץ|המליצה)\w* (?:לי )?(?:ש)?(?:כדאי )?(?:לי )?(?:פשוט )?לשלם", t)
            # מנהל 261 (q13-05): «עורך הדין שלי אמר שזה בסדר לשלם בתשלומים, אפשר לחלק ל-4?» = בקשת פריסה
            or _s(r"(?:אמר|אמרה|אמרו|המליצ|המליצה)\w* (?:לי )?ש(?:זה |זאת )?(?:בסדר|אפשר|מותר|כדאי|הגיוני) (?:לי )?(?:ל)?(?:שלמ|לשלמ|לפרוס|לחלק)", t)) \
            and not _s(_KEEPS_LEGAL, t):  # critic סבב 79: ייצוג ⇒ נשאר legal (לא פונים ישירות למיוצג)
        found.discard(Intent.LEGAL)
    # critic סבב 79: «don't remove me / no need to remove» ⇒ לא הסרה (כמו «לא צריך להסיר» בעברית) — רק אם אין הסרה אחרת
    if Intent.OPT_OUT in found:
        t2 = re.sub(r"\b(?:please )?(?:don'?t|do not|no need to|you don'?t need to)\s+(?:remove|unsubscribe|take)\b[^.!?,]*",
                    " ", t, flags=re.I)
        if t2 != t and not _hits(RX[Intent.OPT_OUT], t2):
            found.discard(Intent.OPT_OUT)
    # מנהל 261 (q13-13 🔴): «הבן שלי לומד אצלכם, הוא בן 12 — אני משלמת ב-20» = הורה שכותב על ילד, לא קטין שענה.
    # גיל ילד + הכותב/ת מתחייב/ת בגוף ראשון, בלי סימן שהילד קיבל/ענה/ישלם ⇒ לא קטין. «הטלפון של הבן שלי, הוא בן 12» ⇒ נשאר.
    if Intent.MINOR in found and _s(r"(?:הבנ|הבת|הילד|הילדה|הנכד|הנכדה|בני|בתי)(?: שלי)?(?![\w])", t) \
            and not _s(r"טלפונ|פלאפונ|נייד|מכשיר|מספר|הודעה|הודעות|מסרונ|סמס|קיבל|קיבלה|ענה|ענתה|כתב|כתבה|ראה|ראתה"
                       r"|אני (?:רק |עדיינ |בסכ הכל )?(?:בנ|בת|קטינ|קטינה|ילד|ילדה|נער|נערה|בכיתה|תלמיד)", t) \
            and not _s(r"ישלמ|תשלמ|יעביר|תעביר|יסדר|תסדר", t) and not re.search(r"\b(?:i'?m|i\s+am)\b", t) \
            and _s(r"(?<![\w])(?:אני |אנחנו )?(?:אשלמ|נשלמ|אעביר|נעביר|אסדר|נסדר|משלמת|משלמ|משלמימ|מעבירה|מעביר)(?![\w])", t):
        found.discard(Intent.MINOR)
    # "הנכד בן 16 ישלם בשבילי" — הקטין משלם עבור המבוגר, לא עונה במקומו (qa3) ⇒ לא קטין
    if Intent.MINOR in found and _s(r"(?:ישלם|תשלם|יעביר|תעביר|יסדר|תסדר)\w*\s+(?:\w+\s+){0,2}(?:בשבילי|עבורי|במקומי|לכם)", t) \
            and not _s(r"ענה|ענתה|קיבל|קיבלה|ראה|ראתה|הטלפון של|המספר של|המכשיר של|אל תכתבו|תפסיקו|אני (?:בן|בת|קטין)", t):
        found.discard(Intent.MINOR)
    # סבב 10: "אל תשלחו מיילים, רק הודעה לנייד" = העדפת ערוץ, לא הסרה — אם אין מילת-תמידיות ויש ערוץ חלופי מבוקש.
    # (עם "יותר/שוב/אף פעם/שום" ⇒ נשאר הסרה, לפי critic סבב 89: הסרה מכובדת + כרטיס.)
    if Intent.OPT_OUT in found and _s(r"(?:^|\W)רק\s+(?:ב|ל|דרך\s+)?(?:מייל|אימייל|סמס|SMS|מסרונ|הודעה|נייד|טלפון|הודעת טקסט)", t) \
            and not _s(r"יותר|שוב|אף פעם|בכלל|לעולם|שום|מהרשימה|תסירו|הסירו|להסיר|הסר(?![\w])|stop"
                       r"|סטופ|עצור|עצרו|תעצרו", t):  # critic סבב 91: מילת הסרה מפורשת ⇒ נשאר הסרה
        found.discard(Intent.OPT_OUT)
    # "טעות בשם/בכתובת… אבל לא נורא/זה בסדר, אשלם" ⇒ לא מחלוקת (self4)
    if Intent.DISPUTE in found and _s(r"טעות (?:קטנה )?ב(?:שם|כתובת|איות|תאריך)", t) \
            and _s(r"(?:אבל|אך)\s+(?:זה |לא )?(?:בסדר|נורא|משנה|חשוב)|אשלם|אעביר|נשלם", t) and not _s(_KEEPS_DISPUTE, t):
        found.discard(Intent.DISPUTE)
    # "stop calling me sir/madam" = כינוי, לא בקשת הפסקת פנייה (self4)
    if Intent.OPT_OUT in found and _s(r"\bstop calling me (?:sir|madam|ma'?am|mr|mrs|ms|bro|dude|that|names|by)\b", t):
        found.discard(Intent.OPT_OUT)
    # בקשת קבלה / "send me the invoice again" ⇒ copy_request (הענף מבדיל קבלה מהעתק חשבונית)
    if not (found - {Intent.UNKNOWN, Intent.THANKS}) and (_s(_RECEIPT, t) or _s(r"\b(?:re)?send\b.{0,20}\binvoice\b", t)):
        found.discard(Intent.UNKNOWN)
        found.add(Intent.COPY_REQUEST)
    # שאלה על עו"ד ("אתם עובדים עם עו"ד?") ≠ איום
    if Intent.LEGAL in found and "?" in t and _s(r"(?:אתם|יש לכם|האם)\W+(?:\w+\W+){0,3}(?:עו\"ד|עורכ\w* ה?דין)", t) \
            and not _s(_KEEPS_LEGAL, t):  # critic סבב 80
        found.discard(Intent.LEGAL)
    # מנהל 269 (qa15 q15-19 🔴): «החוג של עורכי הדין הצעירים היה מהמם… אפשר ב-3 תשלומים?» = שם החוג, לא איום ⇒ היה legal
    # דחוף, בלי הצעת פריסה. מוחקים את שם החוג ובודקים שוב; כל אזכור אחר / מילת הליך ⇒ נשאר legal.
    if Intent.LEGAL in found:
        t2 = re.sub(r"(?:חוג|קורס|סדנ\w*|שיעור\w*|קייטנ\w*|class|course|workshop|camp)\s+(?:של\s+)?(?:ה|ל)?"
                    r"(?:עורכי|עורך|עורכת|עו\"ד)(?:\s+(?:ה)?די[נן])?(?:\s+(?:ה)?(?:צעיר|קטנ)\w*)?"
                    r"|\b(?:young\s+|junior\s+|little\s+)?lawyers?\s+(?:class|course|workshop|camp|club)\b",
                    " ", t, flags=re.I)
        if t2 != t and not _hits(RX[Intent.LEGAL], t2) and not _s(_KEEPS_LEGAL, t):
            found.discard(Intent.LEGAL)
            if not found:
                found.add(Intent.UNKNOWN)
    # מנהל 269 (qa15 q15-26): «אין לי כרגע איך לשלם 😔» = אין כסף (מאיפה לשלם), לא «איך משלמים» ⇒ היה how_to_pay + קישור.
    # «אין לי מושג איך לשלם» / «אין לי קישור, איך לשלם?» ⇒ נשאר how_to_pay.
    if _s(r"(?:^|[\s,.;!?(])אינ\s+לי\s+(?:כרגע\s+|עכשיו\s+|בינתיימ\s+|כעת\s+|החודש\s+|באמת\s+)?(?:מ)?(?:איכ|ממה|במה|מאיפה|מאיפו)\s+לשלמ"
          r"(?![\w])", t) and not _s(r"מושג|קישור|לינק|פרטי|מספר חשבונ", t):
        found.discard(Intent.HOW_TO_PAY)
        found.discard(Intent.UNKNOWN)
        found.add(Intent.CANT_PAY)
    # "אם לא אשלם…?" = שאלה על השלכות, לא סירוב
    if Intent.DISPUTE in found and _s(r"(?:^|\W)(?:ו?אם|מה קורה אם|מה יקרה אם)\s+לא\s+(?:אשלם|נשלם|אעביר)", t) \
            and not _s(_KEEPS_DISPUTE, t):  # critic סבב 80
        found.discard(Intent.DISPUTE)
    # critic סבב 108: «אם הביטוח ישלם…» = תנאי, לא הבטחה (בעל העסק צריך לדעת שהתשלום תלוי בצד שלישי)
    if Intent.PROMISE in found and _s(r"(?:^|\W)(?:רק\s+)?אם\s+(?:ה)?(?:ביטוח|חברת\s+ה?ביטוח)", t) and not _s(
            r"(?<![\w])(?:אשלם|נשלם|אעביר|נעביר)(?![\w])", t):
        found.discard(Intent.PROMISE)
    # "אני עורכת דין" (זהות, לא איום) ⇒ לא legal, אלא אם יש גם מילת הליך
    if Intent.LEGAL in found and _s(r"אני (?:עורכ\w*|עו\"ד)(?: דין)?(?: בעצמי| במקצוע)?", t) and not _s(
            _KEEPS_LEGAL + r"|שלי (?:י|ת)", t):
        found.discard(Intent.LEGAL)
    # "שלחו לינק ואשלם" — בלי תאריך, הדבר המועיל הוא הקישור
    if Intent.PROMISE in found and Intent.HOW_TO_PAY in found and ctx is not None \
            and extract_date_ctx(t, ctx)[0] is None:
        found.discard(Intent.PROMISE)
    # מנהל 248: חשש מהונאה גובר על «איך משלמים/הקישור» — לא דוחפים קישור למי שחושש לפתוח אותו
    if Intent.WHO_IS_THIS in found and _s(_PHISH, t):
        found.discard(Intent.HOW_TO_PAY)
        found.discard(Intent.UNKNOWN)
    # מנהל 258 (qa11 q11-28 🔴): «טוב שילמתי עכשיו את הכל» במצב PROMISED ⇒ «עכשיו» נקרא כמועד ⇒ promise משני.
    # טענת תשלום בעבר בלי פועל עתיד ובלי יתרה («את השאר אשלם ב-20») ⇒ אין הבטחה.
    if Intent.PAID_CLAIM in found and Intent.PROMISE in found and _s(_claims_paid, t) and \
            not _s(_PROMISE_VERB_HE + r"|(?:ה)?(?:שאר|יתרה)|(?:אשלמ|אעביר|נשלמ|נעביר)", t) and \
            not re.search(_PROMISE_VERB_EN + r"|\b(?:the\s+)?(?:rest|remaining|balance)\b", t):
        found.discard(Intent.PROMISE)
    if Intent.THANKS in found and len(found) > 1:
        found.discard(Intent.THANKS)
    if Intent.PLAN_ACCEPT in found and (found & {Intent.DISPUTE, Intent.OPT_OUT, Intent.LEGAL}):
        found.discard(Intent.PLAN_ACCEPT)
    if Intent.WRONG_PERSON in found and Intent.DISPUTE in found and \
            _s(r"טעות (?:ב)?(?:מספר|מס')|מספר (?:שגוי|לא נכון)|(?:מספר|טלפון|נייד)(?:\s+ה?זה)?\s+(?:לא|אינו)\s+שלי"
               r"|לא\s+(?:ה)?(?:מספר|טלפון|נייד)\s+שלי", t):  # critic סבב 120
        found.discard(Intent.DISPUTE)
    # "פיטרו... ואני מבקש תשלומים" — שני האותות נשמרים; הבטחה בלי תאריך מעל כוונת פריסה ⇒ פריסה עיקרית
    if not found:
        found.add(Intent.UNKNOWN)
    out = [i for i in PRIORITY if i in found]
    # סט משפט xl-29: «הייתי במילואים, מעביר השבוע» — המילואים הם הסבר לעיכוב, לא חוסר יכולת.
    # הבטחה עיקרית; CANT_PAY נשאר משני ⇒ תגית reservist + השהיה + כרטיס לבעל העסק נשמרים.
    if Intent.CANT_PAY in found and Intent.PROMISE in found and _s(_RESERVIST_PAST, t) and \
            not _hits(RX[Intent.CANT_PAY], re.sub(_RESERVIST_PAST, " ", t)):
        out.remove(Intent.PROMISE)
        out.insert(out.index(Intent.CANT_PAY), Intent.PROMISE)
    # סט משפט xl-12: «צו פתיחת הליכים בבית המשפט» — בית המשפט הוא של הליך חדלות הפירעון, לא תביעה נגדנו.
    # חוסר יכולת (חדלות) עיקרי; LEGAL נשאר משני ⇒ תגית legal + דחוף + השהיה נשמרים.
    if out[:2] == [Intent.LEGAL, Intent.CANT_PAY] and _s(_INSOLVENCY, t) and \
            not _hits(RX[Intent.LEGAL], re.sub(r"(?:ב|מ|ל)?בית (?:ה)?משפט|(?:ה)?נאמנ", " ", t)):
        out[0], out[1] = Intent.CANT_PAY, Intent.LEGAL
    return out


_EN_NOT_NAMES = frozenset(
    "I Sure Able Interested Paying Going Home Available Happy Ok Okay Fine Here There The A An This That It Your You "
    "Ignoring Refusing Trying Asking Saying Angry Upset Mad Kidding Joking Rich Responsible Liable Aware Satisfied "
    "Comfortable Convinced Certain Done Ready Free Back In Out Well Feeling Working Receiving Getting Paid Yet Sorry "
    "Hebrew English Israeli A Mr Mrs Ms Dr Please Thanks Thank Just Really Even Only Actually Still Always Never "
    "Monday Tuesday Wednesday Thursday Friday Saturday Sunday January February March April May June July August "
    "September October November December Bit Paybox Gmail Google Whatsapp Visa Mastercard Amex Paypal".split())
_INSOLVENCY = r"פשיטת רגל|חדלות פירעונ|צו כינוס|צו פתיחת הליכימ|הליכ חדלות|כונס נכסימ"
_RESERVIST_PAST = r"(?:הייתי|חזרתי|יצאתי|השתחררתי|שוחררתי)\s+(?:מ|ב)?(?:ה)?מילואי[םמ]"
# שאלה על העברת המידע לאחרים («מי עוד קיבל», «למי נתתם») ⇒ בעל העסק. «מאיפה יש לכם את המספר» לבד = זיהוי (d146)
_DATA_SOURCE = (r"מי עוד (?:קיבל|קיבלה|קיבלו|רואה|ראה|יודע)|למי (?:עוד )?(?:נתתם|העברתם|מסרתם|מכרתם)"
                r"|(?:נתתם|העברתם|מסרתם|מכרתם) (?:את )?(?:ה)?(?:פרטים|מספר|טלפון|מייל) (?:שלי )?ל")


# ═══════════════════════════ מעקות ═══════════════════════════
# בדיקות ייחודיות לשיחה, מעבר למסנן המשפטי המשותף (app/compliance.py)
CONVERSATION_BANNED: tuple[tuple[str, re.Pattern[str]], ...] = (
    ("payment_confirmed", re.compile(r"התשלום (?:התקבל|נקלט|אושר)|קיבלנו את התשלום|(?:החשבונית|החוב) (?:נסגר|סולק|שולם)")),
    ("promise_waiver", re.compile(r"לא תצטרכו לשלם|אין צורך לשלם|בוטל(?:ה)? החשבונית")),
    ("whatsapp", re.compile(r"וואטסאפ|ווטסאפ|whatsapp", re.IGNORECASE)),
    ("unfilled_placeholder", re.compile(r"\{\w+\}|\{\{\d+\}\}")),
)


def frame(body: str, ctx: Context) -> str:
    """שם העסק בתחילת כל הודעה (§3.1 סעיף 1)."""
    if ctx.channel == "email":
        return f"{ctx.business}\n\n{body}"
    return f"{ctx.business}: {body}"


def check_reply(text: str, ctx: Context, intent: Intent) -> list[str]:
    rules = compliance.Rules(business=ctx.business, payment_link=ctx.payment_link,
                             channel=ctx.channel)
    issues = compliance.violations(text, rules)
    issues += [name for name, rx in CONVERSATION_BANNED if rx.search(text)]
    if intent == Intent.WRONG_PERSON:
        # לא חושפים לאדם זר שם/סכום/מספר חשבונית
        if ctx.first_name and ctx.first_name in text:
            issues.append("privacy_name")
        if re.search(r"₪|\d{3,}", text):
            issues.append("privacy_amount")
    return issues


_PHONE_RX = re.compile(r"\+?\d[\d\- ]{7,}\d")
_EMAIL_RX = re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+")


def redact_for_llm(text: str, ctx: Context) -> str:
    """מזעור לפני שליחה ל-LLM בחו"ל (ר-9): בלי שם, טלפון, מייל, מספר חשבונית, ת"ז."""
    out = _EMAIL_RX.sub("[מייל]", text or "")
    out = _PHONE_RX.sub("[טלפון]", out)
    for inv in ctx.invoices:
        if inv.number:
            out = out.replace(inv.number, "[מס׳]")
    for part in (ctx.customer_name or "").split():
        if len(part) >= 2:
            out = re.sub(r"(?<![\w])" + re.escape(part) + r"(?![\w])", "[שם]", out)
    if ctx.business:
        out = out.replace(ctx.business, "[העסק]")
    return re.sub(r"\b\d{9}\b", "[ת״ז]", out)


# ═══════════════════════════ הצעת פריסה ═══════════════════════════
def propose_plan(ctx: Context, requested: int | None, start: date | None = None) -> tuple[Installment, ...]:
    if ctx.mixed_currency or ctx.manual_old:
        return ()   # אין סה״כ אחד לפרוס (critic: הצעה יצאה בלי שהסדר נרשם) / ר-7: ידני בלבד
    total = ctx.total_agorot
    if total <= 0:
        return ()
    p = ctx.policy
    max_by_min = max(1, total // max(1, p.min_installment_agorot))
    n = max(1, min(requested or p.default_installments, p.max_installments, max_by_min))
    if n < 2:
        return ()
    first = start or (ctx.today + timedelta(days=p.first_installment_in_days))
    base, rem = divmod(total, n)
    return tuple(Installment(i + 1, _add_months(first, i), base + (rem if i == 0 else 0))
                 for i in range(n))


def _he_date(d: date) -> str:
    names = {6: "ראשון", 0: "שני", 1: "שלישי", 2: "רביעי", 3: "חמישי", 4: "שישי", 5: "שבת"}
    return f"יום {names[d.weekday()]} {d.day}.{d.month}"


def plan_lines(plan: tuple[Installment, ...], currency: str = "ILS") -> str:
    if not plan:
        return ""
    same = len({i.amount_agorot for i in plan[1:]}) <= 1
    if same and len(plan) > 2:
        first, rest = plan[0], plan[1]
        if first.amount_agorot == rest.amount_agorot:
            return (f"{len(plan)} תשלומים חודשיים של {fmt_amount(first.amount_agorot, currency)}, "
                    f"החל מ-{first.due.day}.{first.due.month}")
        return (f"תשלום ראשון {fmt_amount(first.amount_agorot, currency)} ב-{first.due.day}.{first.due.month}, "
                f"ואחריו {len(plan) - 1} תשלומים חודשיים של {fmt_amount(rest.amount_agorot, currency)}")
    return ", ".join(f"{fmt_amount(i.amount_agorot, currency)} ב-{i.due.day}.{i.due.month}" for i in plan)


# ═══════════════════════════ נוסחים ═══════════════════════════
def _hi(ctx: Context) -> str:
    return f"{ctx.first_name}, " if ctx.first_name else ""


def _numbers(ctx: Context) -> str:
    nums = [i.number for i in ctx.invoices if i.number]   # הפעלה 116: מספר ריק ⇒ לא «חשבונית »
    if not nums:
        return ""
    return ("חשבונית " + nums[0]) if len(nums) == 1 else ("חשבוניות " + ", ".join(nums))


# ═══════════════════════════ ההחלטה ═══════════════════════════
def respond(text: str, ctx: Context, *, llm: LLMClassifier | None = None,
            drafter: LLMDrafter | None = None) -> Decision:
    t = normalize(text)
    lang = foreign_language(text)
    if lang:
        # ערבית/רוסית: אין הבטחת תמיכה — עוצרים אוטומציה ומעבירים לבעל העסק, בלי ניחוש ובלי LLM
        return _foreign(lang, text, ctx)
    intents = detect(text, ctx)
    # רצפת הגנה: תבניות מגינות שנתפסו בטקסט הגולמי לפני עידונים (חוקי discard)
    raw_protective = {it for it in _FLOOR_INTENTS if _hits(RX[it], t, negatable=it in NEGATABLE)}
    confidence = "rules"
    if intents == [Intent.UNKNOWN] and llm is not None and t:
        try:
            got = Intent(str(llm.classify(redact_for_llm(text, ctx))).strip().lower())
            # ה-LLM לא יכול לבחור כוונות מבוססות-הקשר או "תודה" שמשתיקה את בעל העסק
            if got not in STATEFUL and got != Intent.THANKS:
                intents, confidence = [got], "llm"
        except Exception as exc:  # noqa: BLE001 — LLM שבור ⇒ נשארים ב-UNKNOWN
            log.warning("llm classify failed: %s", exc)
    if intents == [Intent.UNKNOWN]:
        confidence = "none"
    d = _decide(t, intents, ctx)
    dropped = raw_protective - set(d.all_intents)
    if dropped and t:
        # שורש משותף לרגרסיות (critic 80/88/91): עידון הוריד כוונה מגינה ולא בא דבר במקומה ⇒ לפחות השהיה + כרטיס
        names = ", ".join(sorted(i.value for i in dropped))
        # critic סבב 93 🟡: לקוח שרוצה לשלם (קישור/הבטחה) ושנפל אצלו רק אזכור עו"ד/מחלוקת ⇒ כרטיס בלי השהיה.
        # הסרה/מספר שגוי/קטין/מצוקה שנפלו ⇒ תמיד השהיה.
        payer_only = d.intent in (Intent.HOW_TO_PAY, Intent.PROMISE) and dropped <= {Intent.LEGAL, Intent.DISPUTE}
        d = replace(
            d, stop=d.stop if (d.stop != Stop.NONE or payer_only) else Stop.PAUSE,
            escalate=max(d.escalate, Escalation.NORMAL, key=_esc_rank),
            tags=d.tags + ("protective_floor",),
            owner_actions=d.owner_actions + (f"לבדוק: בהודעה יש סימן ל-{names} שהמנוע לא אישר — להחליט אם לעצור",))
    d = replace(d, confidence=confidence, owner_summary=_with_quote(d.owner_summary, text))
    if confidence == "llm" and d.escalate == Escalation.NONE:
        d = replace(d, escalate=Escalation.NORMAL, tags=d.tags + ("llm_classified",))
    # מגן לולאה: אחרי X תשובות של הבוט — רק בעל העסק
    if d.reply and ctx.bot_turns >= ctx.policy.max_bot_turns and d.intent != Intent.OPT_OUT:
        d = replace(d, reply=None, auto_send=False,
                    escalate=max(d.escalate, Escalation.NORMAL, key=_esc_rank),
                    tags=d.tags + ("bot_turn_limit",),
                    owner_actions=d.owner_actions + ("השיחה ארוכה — להמשיך אישית",))
    # ניסוח LLM (אופציונלי) — חייב לעבור מעקה, אחרת נשארים עם הנוסח הקבוע
    if d.reply and drafter is not None:
        try:
            alt = drafter.draft(d.intent, d.reply, ctx)
            if isinstance(alt, str) and alt.strip() and \
                    not check_reply(frame(alt.strip(), ctx), ctx, d.intent):
                d = replace(d, reply=alt.strip(), auto_send=False, tags=d.tags + ("llm_drafted",))
        except Exception as exc:  # noqa: BLE001 — מנסח שבור ⇒ הנוסח הקבוע
            log.warning("llm draft failed: %s", exc)
    if d.reply:
        d = replace(d, reply=frame(d.reply, ctx))
        issues = check_reply(d.reply, ctx, d.intent)
        if issues:  # נוסח קבוע שנכשל — באג. לא שולחים; בעל העסק מטפל
            d = replace(d, reply=None, auto_send=False, guardrail_issues=tuple(issues),
                        escalate=max(d.escalate, Escalation.NORMAL, key=_esc_rank))
    return d


_ARABIC = re.compile("[\u0600-\u06FF\u0750-\u077F]")
_CYRILLIC = re.compile("[\u0400-\u04FF]")
_HEB = re.compile("[\u05D0-\u05EA]")


def foreign_language(text: str) -> str | None:
    """'ar' / 'ru' כשרוב האותיות בכתב ערבי/קירילי, אחרת None."""
    ar, ru = len(_ARABIC.findall(text or "")), len(_CYRILLIC.findall(text or ""))
    he = len(_HEB.findall(text or ""))
    if max(ar, ru) == 0 or max(ar, ru) < he:
        return None
    return "ar" if ar >= ru else "ru"


# בקשת הסרה בשפה זרה — רשימה קצרה ושמרנית. אין כאן "תמיכה" בשפה: רק לא ממשיכים לשלוח למי שביקש.
_FOREIGN_STOP = re.compile(
    r"не\s+(?:пиш|присыла|отправля|беспоко)|перестаньте|прекратите|отпиш|больше\s+не\s+(?:пиш|присыла)|stop"
    r"|توقف|لا\s*ترسل|عدم\s+(?:مراسلت|إرسال|الإرسال)|إلغاء\s+الاشتراك|كفى", re.IGNORECASE)


def _foreign(lang: str, text: str, ctx: Context) -> Decision:
    name = ctx.customer_name or "הלקוח/ה"
    label = {"ar": "ערבית", "ru": "רוסית"}[lang]
    if _FOREIGN_STOP.search(text or ""):
        return Decision(
            intent=Intent.OPT_OUT, secondary=(), reply=None, auto_send=False,
            escalate=Escalation.NORMAL, stop=Stop.PERMANENT, pause_until=None, next_state=State.OPTED_OUT,
            owner_summary=f"🌐 {name} ביקש/ה ב{label} להפסיק לקבל הודעות: \"{_clip(text)}\". הוסר/ה לצמיתות.",
            owner_actions=("לוודא בתרגום שזו אכן בקשת הסרה",),
            tags=("foreign_language", f"lang:{lang}"), confidence="rules")
    # critic סבב 112: מצוקה/קטין בשפה זרה ⇒ דחוף (מייל לבעלים) + תווית בעברית; עדיין בלי מענה אוטומטי
    if _FOREIGN_DISTRESS.search(text or "") or _FOREIGN_MINOR.search(text or ""):
        kind = "ייתכן מצוקה" if _FOREIGN_DISTRESS.search(text or "") else "ייתכן קטין"
        intent = Intent.DISTRESS if kind == "ייתכן מצוקה" else Intent.MINOR
        return Decision(
            intent=intent, secondary=(), reply=None, auto_send=False,
            escalate=Escalation.URGENT, stop=Stop.PAUSE, pause_until=None, next_state=State.AWAITING_OWNER,
            owner_summary=f"🚨 {kind} — {name} כתב/ה ב{label}: \"{_clip(text)}\". התזכורות נעצרו; נדרש מענה אישי דחוף.",
            owner_actions=("לתרגם ולפנות אישית בהקדם", "לא לחדש תזכורות לפני בירור"),
            tags=("foreign_language", f"lang:{lang}", "minor" if intent == Intent.MINOR else "sensitive"),
            confidence="rules")
    # critic סבב 113: רמז בעברית לבעל עסק שלא קורא את השפה; עו״ד/מחלוקת ⇒ דחוף. הכוונה לא משתנה (אישור אחרי תרגום)
    hint = next((h for rx, h, _u in _FOREIGN_HINTS if rx.search(text or "")), None)
    urgent = any(u and rx.search(text or "") for rx, _h, u in _FOREIGN_HINTS)
    return Decision(
        intent=Intent.UNKNOWN, secondary=(), reply=None, auto_send=False,
        escalate=Escalation.URGENT if urgent else Escalation.NORMAL, stop=Stop.PAUSE, pause_until=None,
        next_state=State.AWAITING_OWNER,
        owner_summary=(f"🌐 {name} השיב/ה ב{label}: \"{_clip(text)}\". "
                       + (f"ייתכן: {hint} (לוודא בתרגום). " if hint else "")
                       + "האוטומציה נעצרה; נדרש מענה אישי."),
        owner_actions=("לקרוא/לתרגם ולהשיב אישית", "לחדש תזכורות רק אחרי שבירור"),
        tags=("foreign_language", f"lang:{lang}"), confidence="none")


# critic סבב 112: סימני מצוקה/קטין בסיסיים ברוסית ובערבית (לא תרגום מלא — רק כדי להסלים לדחוף)
_FOREIGN_DISTRESS = re.compile(
    r"умереть|умру|покончить с собой|убить себя|самоубий|не (?:хочу|могу) (?:больше )?жить|жить не (?:хочу|могу)"
    r"|أموت|انتحار|أنتحر|انتحر|لا أريد أن أعيش|لا أستطيع العيش|أقتل نفسي", re.I)
_FOREIGN_MINOR = re.compile(
    r"мне\s+(?:1[0-7]|[5-9])\s+(?:лет|год)|عمري\s+(?:1[0-7]|١[٠-٧]|[5-9]|[٥-٩])\s+(?:سنة|سنوات|عام)", re.I)
_FOREIGN_HINTS = (   # (תבנית, רמז בעברית, דחוף?)
    (re.compile(r"адвокат|юрист|суд(?![а-я]*\s*(?:-|\s)?(?:поч))|المحامي|محامي|المحكمة|محكمة", re.I), "פנייה לעו״ד / משפטית", True),
    (re.compile(r"ничего не должен|не должна|не заказывал|не заказывала|это ошибка|неправильн\w* сумм"
                r"|لم أطلب|لا أدين|هذا خطأ|المبلغ خطأ|مبلغ غير صحيح", re.I), "מחלוקת על החוב", True),
    (re.compile(r"не мой номер|ошиблись номером|не тот номер|ليس رقمي|رقم خطأ|الرقم الخطأ", re.I), "מספר שגוי", False),
    (re.compile(r"уже (?:за)?платил|уже оплатил|я оплатил|دفعت|تم الدفع|سددت", re.I), "טוען/ת ששילם/ה", False),
)
_RECEIPT = r"(?<![\w])(?:ה|ו)?(?:קבלה|קבלות)(?![\w])|\breceipts?\b"
_FLOOR_INTENTS = (Intent.OPT_OUT, Intent.DISPUTE, Intent.LEGAL, Intent.DISTRESS, Intent.MINOR, Intent.WRONG_PERSON)


def _esc_rank(e: Escalation) -> int:
    return {Escalation.NONE: 0, Escalation.NORMAL: 1, Escalation.URGENT: 2}[e]


def _stop_rank(s: Stop) -> int:
    return {Stop.NONE: 0, Stop.PAUSE: 1, Stop.PERMANENT: 2}[s]


_INV_FIELD = r"(?:ה)?(?:שם|כתובת|ח\.?פ\.?|ע\.?מ\.?|ת\.?ז\.?|מספר (?:ה)?עוסק|תאריך|איות)"
_INV_OWN = r"(?:\s+(?:שלי|שלנו|של\s+(?:ה)?(?:חברה|עסק|עמותה)))?"


def _invoice_fix(t: str) -> bool:
    """בקשה לתקן/להנפיק מחדש חשבונית בגלל פרט שגוי (לא מחלוקת על הסכום)."""
    return bool(
        _s(r"טעות\s+(?:\w+\s+){0,2}ב" + _INV_FIELD + r"(?!\w)", t)
        or _s(r"(?:תתקנו|תקנו|לתקן|תוציאו|תנפיקו|תשלחו)\s+(?:לי\s+)?(?:את\s+)?" + _INV_FIELD + r"\s+(?:\w+\s+){0,1}ב?(?:ה)?חשבונית", t)
        or _s(r"חשבונית\s+(?:מתוקנת|חדשה|מעודכנת)|(?:ה)?חשבונית\s+(?:\w+\s+){0,2}על\s+שם\s+(?:ה)?(?:חברה|עסק|העמותה)", t)
        # מנהל הפעלה 241: «השם שלי בחשבונית שגוי» / «בחשבונית השם שגוי» — כינוי-שייכות בין השדה לחשבונית
        or _s(r"" + _INV_FIELD + _INV_OWN + r"\s+(?:ב|על\s+)?(?:ה)?חשבונית\s+(?:\w+\s+)?(?:לא\s+נכונ\w*|שגוי\w*)", t)
        or _s(r"(?:ב|על\s+)(?:ה)?חשבונית\s+" + _INV_FIELD + _INV_OWN + r"\s+(?:לא\s+נכונ\w*|שגוי\w*)", t)
        or _s(r"\bwrong\s+(?:name|address|date|company)\s+on\s+the\s+invoice\b|\b(?:fix|correct|reissue)\s+the\s+invoice\b"
              r"|\bcorrected\s+invoice\b"
              r"|\b(?:my|the|our)\s+(?:company\s+)?(?:name|address|date|vat\s+number|tax\s+id)\s+on\s+the\s+invoice\s+is\s+"
              r"(?:wrong|incorrect|misspelled)\b", t))


def _decide(t: str, intents: list[Intent], ctx: Context) -> Decision:
    primary, secondary = intents[0], tuple(intents[1:])
    allset = set(intents)
    p = ctx.policy
    hi, sig = _hi(ctx), ""
    name = ctx.customer_name or "הלקוח/ה"
    total = ctx.total_text()
    reply: str | None = None
    esc, stop = Escalation.NONE, Stop.NONE
    pause_until: date | None = None
    state = ctx.state
    plan: tuple[Installment, ...] = ()
    promise_date: date | None = None
    paid: int | None = None
    summary = ""
    actions: list[str] = []
    tags: list[str] = []

    def bump(e: Escalation = Escalation.NONE, s: Stop = Stop.NONE) -> None:
        nonlocal esc, stop
        if _esc_rank(e) > _esc_rank(esc):
            esc = e
        if _stop_rank(s) > _stop_rank(stop):
            stop = s

    # ── השפעות מכל הכוונות (איחוד) ──
    if Intent.MINOR in allset:
        bump(Escalation.URGENT, Stop.PAUSE)
        tags += ["minor", "sensitive"]
    if Intent.DISTRESS in allset:
        bump(Escalation.URGENT, Stop.PAUSE)
        tags.append("sensitive")
    if Intent.OPT_OUT in allset:
        bump(s=Stop.PERMANENT)
    if Intent.WRONG_PERSON in allset:
        bump(Escalation.NORMAL, Stop.PERMANENT)
    if Intent.LEGAL in allset:
        bump(Escalation.URGENT, Stop.PAUSE)
        tags.append("legal")
    if Intent.DISPUTE in allset:
        bump(Escalation.URGENT, Stop.PAUSE)
    if Intent.PAID_CLAIM in allset:
        bump(Escalation.NORMAL, Stop.PAUSE)
    if Intent.CANT_PAY in allset:
        bump(Escalation.NORMAL, Stop.PAUSE)
        if _s(r"מילואים|צו 8|צו שמונה", t):
            tags.append("reservist")
        if _s(r"חולה|מחלה|מאושפז|אשפוז|ניתוח|כימו|שבעה|(?:(?:אני|אנחנו|אנו|אנחנו עדיין|עדיין) ב?אבל|ימי (?:ה)?אבל|בתקופת (?:ה)?אבל|שנת (?:ה)?אבל|באבל)|נפטר|לעולמ|לוויה|בבית ה?חולימ|בבי\"?ח|בטיפול נמרצ"
              r"|\bpassed away\b|\bfuneral\b|\bmourning\b|\bhospital|\bsurgery\b|\bicu\b", t):
            tags.append("sensitive")
            bump(Escalation.URGENT)  # מחלה/אשפוז/אבל — בעל העסק צריך לראות מיד (qa2)
        # ר-6: חדלות פירעון ⇒ אסור לגבות בעצמנו; נפטר ⇒ עזבון — שניהם לבעל העסק בדחיפות
        if _s(r"פשיטת רגל|חדלות פירעון|צו כינוס|צו פתיחת הליכים|הליך חדלות|נאמן (?:בתיק|שמונה)|כונס נכסים"
              r"|(?:תיק|תיקי) איחוד|איחוד תיקים|מעוקל|עיקול|דרך (?:ה)?לשכה", t):
            tags += ["insolvency", "sensitive"]
            bump(Escalation.URGENT)
        if _s(r"(?:נפטר|נפטרה|הלך לעולמו|הלכה לעולמה) לי (?:ה)?(?:אבא|אמא|בעל|בעלי|אשתי|אישה|בן|בת|אח|אחות)", t) or \
                _s(r"(?:הוא|היא|בעלי|אשתי|אבא|אמא|אבי|אמי|הלקוח|הלקוחה|בעל החשבון)\w*(?: שלי)?[\s,\-–]+(?:\w+[\s,]+)?(?:נפטר|נפטרה|הלך לעולמו|הלכה לעולמה|נהרג|נהרגה)", t):
            tags += ["deceased"]
            bump(Escalation.URGENT)
    if Intent.PLAN_REQUEST in allset or Intent.PLAN_ACCEPT in allset or Intent.PLAN_REJECT in allset:
        bump(Escalation.NORMAL, Stop.PAUSE)
    if Intent.ABUSIVE in allset:
        bump(Escalation.NORMAL)
        tags.append("abusive")
    if Intent.CALLBACK in allset or Intent.COPY_REQUEST in allset:
        bump(Escalation.NORMAL)
    if Intent.UNKNOWN in allset:
        bump(Escalation.NORMAL)
    # מנהל הפעלה 239: בקשה לתקן פרטים בחשבונית (שם/כתובת/ח"פ/תאריך) — גם כשהלקוח מבטיח לשלם — היא עבודה של
    # בעל העסק בחשבונית ירוקה. בלי זה «טעות בשם בחשבונית, תתקנו ואשלם» נענה אוטומטית ואף אחד לא תיקן.
    if _invoice_fix(t):
        bump(Escalation.NORMAL)
        tags.append("invoice_fix")
        actions.append("לתקן את פרטי החשבונית בחשבונית ירוקה ולשלוח ללקוח חשבונית מתוקנת")

    # ── נוסח לפי הכוונה העיקרית ──
    if primary == Intent.MINOR:
        reply = None  # לא מנהלים שיחה על חוב עם קטין
        summary = f"🔴 נראה שמי שענה במספר של {name} הוא קטין. כל האוטומציה נעצרה ולא נשלחה תשובה."
        actions.append("לבדוק פרטי קשר נכונים של בעל החשבון; לא לפנות שוב למספר הזה בלי בירור")
        state = State.AWAITING_OWNER
    elif primary == Intent.DISTRESS:
        reply = (f"{hi}מצטערים מאוד לשמוע. התשלום יכול לחכות — עצרנו את כל התזכורות. "
                 f"אם קשה לכם עכשיו, ער\"ן זמינים בכל שעה בטלפון 1201.{sig}")
        summary = f"⚠️ {name} כתב/ה משהו שנשמע כמו מצוקה קשה. כל התזכורות הושהו."
        actions.append("לקרוא את ההודעה ולפנות אישית ובעדינות — לא לדבר על כסף")
        pause_until = ctx.today + timedelta(days=30)
        state = State.AWAITING_OWNER
    elif primary == Intent.OPT_OUT:
        reply = f"הבקשה התקבלה — לא יישלחו אליכם עוד תזכורות אוטומטיות.{sig}"
        summary = f"{name} ביקש/ה להפסיק לקבל תזכורות. הוסר/ה לצמיתות."
        if Intent.DISPUTE in allset or Intent.LEGAL in allset:
            summary += " ההודעה כוללת גם טענה נגד החוב."
            actions.append("לברר את הטענה אישית")
        # critic סבב 89: הסרה + העדפת ערוץ / כוונת תשלום ⇒ ההסרה נשארת, אבל בעל העסק יודע (לא נעלם בשקט)
        wants_channel = _s(r"(?:רק|אלא)\s+(?:ב|דרך\s+)?(?:ה)?(?:סמס|מסרון|sms|מייל|אימייל|וואטסאפ|ווטסאפ|טלפון|קישור|לינק)"
                           r"|תשלחו\s+(?:לי\s+)?(?:רק\s+)?(?:ה)?(?:קישור|לינק)|\bonly\s+(?:by\s+|via\s+)?(?:sms|text|email)\b", t)
        wants_pay = bool(allset & {Intent.PROMISE, Intent.HOW_TO_PAY, Intent.PLAN_REQUEST}) or _s(
            r"(?<![\w])(?:אשלם|נשלם|משלם|משלמת|משלמים|אעביר|נעביר|מעביר|מעבירה)(?![\w])|\bi(?:'ll| will| am going to)\s+(?:pay|transfer)\b", t)
        # critic סבב 114: «כן… ותפסיקו לשלוח» אחרי הצעת פריסה ⇒ ההסכמה לפריסה לא אובדת בשקט
        accepts_plan = ctx.state == State.AWAITING_PLAN_REPLY and _s(
            r"^\W*(?:כן|מתאים|מאשר|מאשרת|מסכים|מסכימה|בסדר|yes|yeah|yep|ok|okay|sure|that works|deal)(?![\w])", t)
        if wants_channel or wants_pay or accepts_plan:
            bump(Escalation.NORMAL)
            summary += (" ביקש/ה ערוץ אחר." if wants_channel else "") + (" כתב/ה שמתכוון/ת לשלם." if wants_pay else "")
            if accepts_plan:
                summary += " ענה/תה «כן» להצעת הפריסה — ייתכן שמסכים/ה לתשלומים; לברר אישית (ההסרה בתוקף)."
            actions.append("ההסרה בתוקף — לפנות אישית רק אם ביקש/ה ערוץ אחר, או לחכות לתשלום ולסגור את החשבונית")
        state = State.OPTED_OUT
    elif primary == Intent.WRONG_PERSON:
        reply = f"סליחה על ההטרדה! נעדכן את הפרטים אצלנו ולא נפנה שוב למספר הזה.{sig}"
        summary = f"מי שענה במספר של {name} אומר/ת שזה לא הוא/היא. המספר הוסר."
        actions.append("לעדכן טלפון נכון בחשבונית ירוקה")
        state = State.OPTED_OUT
    elif primary == Intent.LEGAL:
        reply = None  # כל מילה עלולה לשמש בהליך — בעל העסק מחליט
        summary = f"🔴 {name} הזכיר/ה עו\"ד / תביעה / תלונה. התזכורות הושהו ולא נשלחה תשובה."
        actions.append("לא להשיב לפני התייעצות; לבדוק את ההיסטוריה של החשבונית")
        state = State.AWAITING_OWNER
    elif primary == Intent.DISPUTE:
        reply = (f"תודה שעדכנתם{(' ' + ctx.first_name) if ctx.first_name else ''}. עצרנו את התזכורות, "
                 f"ונחזור אליכם אישית כדי לברר את העניין.{sig}")
        summary = f"🔴 {name} חולק/ת על החוב: \"{_clip(t)}\". התזכורות הושהו."
        actions.append("לבדוק את הטענה ולחזור ללקוח אישית")
        state = State.AWAITING_OWNER
    elif primary == Intent.PAID_CLAIM:
        paid = extract_paid_amount(t)
        partial = bool(_PARTIAL_WORDS.search(t)) or (
            paid is not None and ctx.total_agorot and paid < ctx.total_agorot)
        if partial:
            tags.append("partial")
            got = f" ({fmt_amount(paid, ctx.currency)})" if paid else ""
            reply = (f"תודה{(' ' + ctx.first_name) if ctx.first_name else ''}! רשמנו שהעברתם חלק מהסכום{got}. "
                     f"נבדוק מול הרישומים ונחזור אליכם לגבי היתרה. "
                     f"אם יש אסמכתא — אפשר לשלוח כאן.{sig}")
            summary = (f"{name} טוען/ת ששילם/ה חלק{got} מתוך {total}. לבדוק ולעדכן יתרה.")
        else:
            reply = (f"תודה שעדכנתם{(' ' + ctx.first_name) if ctx.first_name else ''}! עצרנו את התזכורות "
                     f"ונבדוק את התשלום מול הרישומים שלנו. אם יש אסמכתא (צילום או מספר העברה) — "
                     f"אפשר לשלוח כאן, זה יזרז את הבדיקה.{sig}")
            summary = f"{name} טוען/ת ששילם/ה {total}. התזכורות הושהו עד שתבדקו."
        actions.append("לבדוק בבנק/בסליקה ולסמן בחשבונית ירוקה")
        if Intent.PLAN_REQUEST in allset:
            actions.append("ביקש/ה גם פריסה ליתרה")
        pause_until = ctx.today + timedelta(days=7)
        state = State.AWAITING_OWNER
    elif primary == Intent.PLAN_ACCEPT and (ctx.plan_approved or ctx.state == State.PLAN_PENDING_OWNER):
        # מנהל 265: בעל העסק כבר אישר ושלח את ההסדר, או שהלקוח כבר אישר והוא ממתין לבעל העסק.
        # היה: «ההסדר הועבר לאישור סופי, ואחרי האישור נשלח את פרטי התשלום הראשון» (הבטחה שאף אחד לא מקיים —
        # האישור כבר ניתן) + כרטיס «נדרש אישור סופי שלך» שאין מה לעשות בו; ואישור חוזר ⇒ «לא ברור».
        plan = ctx.offered_plan
        tags.append("plan_confirmed" if ctx.plan_approved else "plan_reconfirm")
        asks = "?" in t or bool(secondary)
        # התשלום הקרוב (לא בהכרח הראשון — אישור חוזר יכול להגיע אחרי שמועד הראשון עבר)
        first = next((i for i in plan if i.due >= ctx.today), None)
        if ctx.plan_approved and first is not None and (ctx.state != State.PLAN_PENDING_OWNER or asks):
            # אישור ראשון של הלקוח (או אישור חוזר עם שאלה) ⇒ אישור ללקוח עם התשלום הקרוב. טיוטה לאישור, כרגיל.
            which = "הראשון" if first is plan[0] else "הבא"
            base = (f"מעולה, תודה{(' ' + ctx.first_name) if ctx.first_name else ''}! ההסדר בתוקף. "
                    f"התשלום {which}: {fmt_amount(first.amount_agorot, ctx.currency)} עד {_he_date(first.due)}.")
            link = f" לתשלום: {ctx.payment_link}" if ctx.payment_link else ""
            reply = f"{base}{link}{sig}"
            if link and not ctx.fits_sms(reply):
                reply = f"{base}{sig}"
            summary = (f"✅ {name} אישר/ה את ההסדר שאישרת ({plan_lines(plan, ctx.currency)}). ההסדר בתוקף — "
                       f"נותר רק לשלוח ללקוח אישור עם מועד התשלום הקרוב.")
            actions.append("לאשר את הודעת האישור ללקוח")
        elif ctx.plan_approved:
            reply = None
            summary = f"✅ {name} אישר/ה שוב את ההסדר שבתוקף ({plan_lines(plan, ctx.currency)}). אין צורך בפעולה."
        else:
            reply = None
            summary = (f"{name} אישר/ה שוב את הצעת הפריסה ({plan_lines(plan, ctx.currency)}). "
                       f"ההסדר ממתין לאישור הסופי שלך ב«הסדרים».")
            if asks:
                actions.append("לקרוא את השאלה ולהשיב אישית")
        if not secondary:
            # אין כאן בקשה חדשה ⇒ בלי כרטיס «דרוש טיפול». שאלה על הסדר שעוד לא אושר ⇒ כרטיס רגיל.
            esc = Escalation.NORMAL if (asks and not ctx.plan_approved) else Escalation.NONE
            if reply is None:   # אישור חוזר בלבד ⇒ כמו «תודה», בלי השהיה חדשה (אישור ראשון שומר את ההשהיה)
                stop = Stop.NONE
        state = State.PLAN_PENDING_OWNER
    elif primary == Intent.PLAN_ACCEPT:
        plan = ctx.offered_plan
        reply = (f"מעולה, תודה{(' ' + ctx.first_name) if ctx.first_name else ''}! ההסדר הועבר לאישור סופי, "
                 f"ואחרי האישור נשלח את פרטי התשלום הראשון.{sig}")
        summary = f"✅ {name} אישר/ה את הצעת הפריסה ({plan_lines(plan, ctx.currency)}). נדרש אישור סופי שלך."
        actions.append("לאשר את ההסדר")
        state = State.PLAN_PENDING_OWNER
    elif primary == Intent.PLAN_REJECT and ctx.state == State.PLAN_PENDING_OWNER and ctx.offered_plan:
        # מנהל 266: הלקוח חוזר בו מהסדר שכבר אישר. לא מבטלים אוטומטית (בעל העסק מחליט, וההסדר נשאר כפי שהוא
        # ב«הסדרים»); כרטיס עם ההסדר ועם ההודעה. חזרה מפורשת ⇒ טיוטת «קיבלנו»; «לא» לבד ⇒ בלי תשובה.
        plan = ()
        tags.append("plan_retract")
        explicit = plan_retract(t)
        if explicit:
            reply = f"{hi}קיבלנו את ההודעה לגבי ההסדר. בעל העסק יבדוק ויחזור אליכם.{sig}"
        what = "ההסדר שאישרת" if ctx.plan_approved else "ההסדר שאישר/ה (עדיין ממתין לאישור שלך)"
        verb = "חוזר/ת בו/ה מ" if explicit else "ייתכן שחוזר/ת בו/ה מ"
        summary = (f"↩️ {name} {verb}{what} ({plan_lines(ctx.offered_plan, ctx.currency)}): \"{_clip(t)}\". "
                   f"ההסדר לא בוטל אוטומטית.")
        if Intent.CANT_PAY in allset:
            summary += " מספר/ת על קושי לעמוד בתשלומים."
        dd, _ = extract_date_ctx(t, ctx)
        if Intent.PROMISE in allset and dd is not None and dd >= ctx.today:
            promise_date = dd
            summary += f" מציע/ה במקום לשלם עד {_he_date(dd)} ({(dd - ctx.today).days} ימים)."
            actions.append(f"לאשר את המועד {_he_date(dd)} או להציע אחר")
        if ctx.plan_approved:
            actions.append("לדבר עם הלקוח/ה; אם ההסדר מתבטל — לבטל אותו ב«הסדרים»")
        else:
            actions.append("לא לאשר את ההסדר ב«הסדרים» לפני שמדברים עם הלקוח/ה")
        state = State.AWAITING_OWNER
    elif primary == Intent.PLAN_REJECT and Intent.PLAN_REQUEST not in allset:
        reply = (f"בסדר גמור. נחזור אליכם כדי למצוא יחד פתרון שמתאים לכם.{sig}")
        summary = f"{name} דחה/תה את הצעת הפריסה: \"{_clip(t)}\"."
        actions.append("להציע הסדר אחר או לדבר אישית")
        # מנהל 253 (qa9 q9-02): «לא, אשלם הכל ב-15 בדצמבר» — המועד נבלע; בעל העסק ראה רק «דחה». נשאר כרטיס, עם המועד.
        dd, _ = extract_date_ctx(t, ctx)   # מנהל 256 (q10-02): «לא… אשלם הכל ב-20» — גם יום בחודש לבד
        if Intent.PROMISE in allset and dd is not None and dd >= ctx.today:
            promise_date = dd
            summary += f" מציע/ה במקום לשלם עד {_he_date(dd)} ({(dd - ctx.today).days} ימים)."
            actions.append(f"לאשר את המועד {_he_date(dd)} או להציע אחר")
        state = State.AWAITING_OWNER
    elif primary in (Intent.PLAN_REQUEST, Intent.PLAN_REJECT, Intent.CANT_PAY):
        requested = extract_installments(t)
        # מנהל 264: שינוי בהסדר שבשיחה — אותו מספר תשלומים, רק מה שביקשו משתנה. נבדק לפני «ספרה לבד = מספר
        # תשלומים»: אחרת «להזיז את התשלום הראשון ל-20» ב-AWAITING_PLAN_REPLY נקרא «20 תשלומים».
        chg = plan_change(t) if primary == Intent.PLAN_REQUEST and _plan_ctx(ctx) else None
        # מנהל 267: המספר שאחרי סמן ההצעה הנגדית קודם למספר הראשון בהודעה («3 תשלומים זה הרבה, אולי 6?» = 6)
        cnt = plan_counter(t, len(ctx.offered_plan), ctx.state == State.PLAN_PENDING_OWNER) \
            if primary in (Intent.PLAN_REQUEST, Intent.PLAN_REJECT) and _plan_ctx(ctx) and (chg is None or chg[1] == "count") \
            else None
        if cnt is not None:
            requested = cnt
        # מנהל 268: סכום חודשי נגדי («300 בחודש זה הרבה, אולי 200?») — הסכום שאחרי הסמן, לא הראשון בהודעה
        camt = plan_counter_amount(t, _plan_monthly(ctx)) \
            if cnt is None and primary in (Intent.PLAN_REQUEST, Intent.PLAN_REJECT) and _plan_ctx(ctx) and chg is None \
            else None
        counter_pending = (cnt is not None or camt is not None) and ctx.state == State.PLAN_PENDING_OWNER
        if counter_pending:
            tags.append("plan_change")
        monthly = camt or extract_monthly_amount(t)
        if not counter_pending and ctx.state == State.PLAN_PENDING_OWNER and ctx.offered_plan and chg is None \
                and primary == Intent.PLAN_REQUEST and monthly and monthly != _plan_monthly(ctx):
            # «אשלם 200 לחודש» / «I can pay 200 a month» אחרי שהלקוח אישר הסדר אחר — גם זה שינוי בהסדר
            counter_pending = True
            tags.append("plan_change")
        # מנהל 268: «אולי 200 בחודש?» ⇒ היה «ביקש/ה 20 תשלומים ⚠️ מעל התקרה» (הספרות הראשונות מתוך 200). יש סכום
        # חודשי ⇒ מספר התשלומים נגזר ממנו; ספרה לבד = מספר שלם של 1–2 ספרות בלבד.
        if requested is None and not monthly and ctx.state == State.AWAITING_PLAN_REPLY and (chg is None or chg[1] == "count"):
            # critic סבב 130: «two fifty a month» = 250, לא «2 תשלומים» — מילת מספר לפני מילת עשרות אינה מספר תשלומים
            m = _s(r"(?<![\d.,])(\d{1,2}(?![\d.,]\d?)(?!\s*(?:לחודש|בחודש))|" + _NUMW + r"|\b(?:" + _EN_INW + r")\b"
                   r"(?![\s-]+(?:twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)\b))", t)
            if m:
                g = m.group(1)
                requested = int(g) if g.isdigit() else (_NUM_WORDS.get(g) or _EN_INST.get(g.lower()))
        chg_card = False
        if chg is not None:
            tags.append("plan_change")
            ch_n, ch_kind = chg
            if ch_kind == "amount":
                monthly = monthly or plan_change_amount(t)
                chg_card = not monthly
            elif ch_kind == "date":
                # רק מועד התשלום הראשון ניתן להזזה בהצעה מחושבת (השאר נגזרים ממנו); תשלום אחר ⇒ בעל העסק
                chg_card = ch_n not in (None, 1)
            elif ch_kind == "other":
                chg_card = True
            if requested is None and ch_kind != "count" and not (ch_kind == "amount" and monthly):
                requested = len(ctx.offered_plan)
        if requested is None and monthly and ctx.total_agorot:
            requested = -(-ctx.total_agorot // monthly)  # עיגול למעלה
        start = None
        if chg is not None and chg[1] == "date" and not chg_card:
            dd = change_date(t, ctx.today)
            # גבול: המועד הרגיל של התשלום הראשון + הדחייה המותרת (מדיניות בעל העסק). מעבר ⇒ בעל העסק מחליט
            if dd is None or dd <= ctx.today or \
                    (dd - ctx.today).days > p.first_installment_in_days + p.max_defer_days:
                chg_card = True
            else:
                start = dd
        else:
            dd, _ = extract_date(t, ctx.today)
            if dd and (dd - ctx.today).days <= p.max_defer_days and dd > ctx.today:
                start = dd
        if requested is None and start is not None and not monthly and _plan_ctx(ctx) and ctx.offered_plan:
            # מנהל 268: «אפשר ב-20 לחודש?» באמצע הצעה = רק המועד זז; מספר התשלומים נשאר (היה: ברירת המחדל, 3 במקום 4)
            requested = len(ctx.offered_plan)
        over = requested is not None and requested > p.max_installments
        sensitive = "reservist" in tags or "sensitive" in tags
        # מנהל 269: אותו הסדר שכבר בשיחה — «אולי 300 בחודש?» / «can we do 300 a month?» / «אשלם 300 לחודש» כשההסדר
        # הוא 300 לחודש, או «אפשר 4 תשלומים?» כשהוצעו 4 — היה: הסדר זהה חדש נרשם (plans 2), ואחרי אישור בעל העסק
        # חזרה ל«ממתין להצעה» עם כפילות ב«הסדרים». עכשיו: בלי הסדר חדש, תשובה שזה בדיוק ההסדר שבשיחה.
        n_cur = len(ctx.offered_plan) if ctx.offered_plan else 0
        same_plan = bool(
            primary == Intent.PLAN_REQUEST and _plan_ctx(ctx) and not sensitive and chg is None
            and cnt in (None, n_cur) and camt is None and not counter_pending and start is None
            and ((monthly and monthly == _plan_monthly(ctx) and requested in (None, n_cur))
                 or (not monthly and requested == n_cur
                     and _s(r"(?:\d{1,2}|" + _NUMW + r")\s*(?:תשלומ|פעמימ|payments|installments|instalments)", t))))
        if p.auto_offer_plan and ctx.invoices and not sensitive and not chg_card and not same_plan:
            plan = propose_plan(ctx, requested, start)
        if same_plan:
            tags.append("plan_same")
            cur = plan_lines(ctx.offered_plan, ctx.currency)
            if ctx.plan_approved:
                head, tail = f"{hi}זה בדיוק ההסדר שבתוקף", "."
                what = "זהה להסדר שאישרת ושבתוקף"
            elif ctx.state == State.PLAN_PENDING_OWNER:
                head, tail = f"{hi}זה בדיוק ההסדר שאישרתם", ". הוא ממתין לאישור סופי, ונעדכן מיד אחריו."
                what = "זהה להסדר שאישר/ה וממתין לאישורך"
            else:
                head, tail = f"{hi}זה בדיוק מה שהצענו", ". מתאים? השיבו \"מאשר\" או כתבו מה מתאים לכם."
                what = "זהה להצעה שנשלחה"
            reply = f"{head}: {cur}{tail}{sig}"
            if not ctx.fits_sms(reply):
                reply = f"{head}{tail}{sig}"
            summary = f"{name} כתב/ה \"{_clip(t)}\" — {what} ({cur}). לא נוצר הסדר חדש."
            esc = Escalation.NONE
            state = ctx.state
        elif chg_card and not sensitive:
            # מנהל 264: שינוי שאי אפשר לחשב בבטחה (תשלום שאינו הראשון, מועד מחוץ לגבולות, «בתחילת החודש»)
            # ⇒ לא מנחשים לוח חדש וגם לא שואלים «עד מתי?» — כרטיס לבעל העסק עם ההסדר הנוכחי והבקשה.
            reply = (f"{hi}קיבלנו את הבקשה לשינוי בהסדר. בעל העסק יבדוק ויחזור אליכם.{sig}")
            summary = (f"🔁 {name} מבקש/ת שינוי בהסדר ({plan_lines(ctx.offered_plan, ctx.currency)}): "
                       f"\"{_clip(t)}\".")
            actions.append("לעדכן את ההסדר (הצעה חדשה ב«הסדרים») או לענות אישית")
            state = State.AWAITING_OWNER
        elif plan:
            intro = {Intent.CANT_PAY: f"{hi}תודה ששיתפתם, אנחנו מבינים. אפשר לפרוס את {total} בלי תוספת: ",
                     }.get(primary, f"{hi}בשמחה. הצעה לפריסת {total} בלי תוספת: ")
            if over:
                intro = f"{hi}אפשר לפרוס עד {p.max_installments} תשלומים בלי תוספת: "
            elif chg is not None or counter_pending:
                intro = f"{hi}בשמחה. הצעה מעודכנת לפריסת {total} בלי תוספת: "
            reply = (intro + plan_lines(plan, ctx.currency) + ". "
                     f"בכפוף לאישור סופי. מתאים? השיבו \"מאשר\" או כתבו מה מתאים לכם.{sig}")
            if not ctx.fits_sms(reply):
                # critic סבב 25: שם עסק ארוך + «קשה לי» + חלוקה לא שווה ⇒ 291 תווים. בעל העסק אישר,
                # השליחה נכשלה, והלקוח לא קיבל כלום. נוסח מקוצר — אותם סכומים ותאריכים.
                reply = (f"{hi}אפשר לפרוס את {total} בלי תוספת: {plan_lines(plan, ctx.currency)}. "
                         f"בכפוף לאישור. מתאים? השיבו \"מאשר\".{sig}")
            state = State.AWAITING_PLAN_REPLY
            summary = f"{name} " + ("סיפר/ה על קושי" if primary == Intent.CANT_PAY else
                                    "ביקש/ה שינוי בהסדר" if chg is not None or counter_pending else "ביקש/ה פריסה") + \
                      (f" ל-{requested} תשלומים" if requested else "") + \
                      f". טיוטת הצעה: {plan_lines(plan, ctx.currency)}."
            if counter_pending:
                # מנהל 267: אחרי שהלקוח כבר אישר — בעל העסק צריך לדעת שזה שינוי, ומה ההסדר הקודם
                summary += (f" 🔁 ההסדר שהלקוח/ה אישר/ה קודם: {plan_lines(ctx.offered_plan, ctx.currency)}"
                            + (" (אושר על ידך; נשאר בתוקף עד שתאשר/י את החדש)." if ctx.plan_approved
                               else " (ממתין לאישורך — לא לאשר את הקודם אם שולחים את החדש)."))
            if over:
                summary += f" ⚠️ ביקש/ה {requested} — מעל התקרה שלך ({p.max_installments})."
                actions.append(f"להחליט אם לאשר {requested} תשלומים")
            if ctx.fits_sms(reply):
                actions.append("לאשר את טיוטת ההצעה לפני שליחה")
            else:   # גם המקוצר לא נכנס ⇒ אין הצעה אוטומטית (לא נרשם הסדר), כרטיס להציע ידנית
                reply = (f"{hi}תודה ששיתפתם. נחזור אליכם אישית כדי למצוא יחד פתרון שמתאים לכם.{sig}")
                summary = summary.replace("טיוטת הצעה:", "לא הוצעה אוטומטית (ארוכה מדי ל-SMS). הצעה מחושבת:")
                plan = ()
                tags.append("plan_too_long_for_sms")
                actions.append("להציע פריסה ידנית (ההצעה ארוכה מדי ל-SMS)")
                state = State.AWAITING_OWNER
        elif ctx.manual_old and p.auto_offer_plan and not sensitive:
            # critic סבב 23 (ר-7): חשבונית מעל 3 שנים ⇒ אין שום אוטומציה, גם לא הצעת פריסה בשיחה
            reply = (f"{hi}תודה ששיתפתם. נחזור אליכם אישית כדי למצוא יחד פתרון שמתאים לכם.{sig}")
            summary = (f"{name} מבקש/ת הסדר/מתקשה לשלם. לא הוצעה פריסה אוטומטית: יש חשבונית "
                       f"פתוחה בת יותר מ-3 שנים.")
            actions.append("להציע הסדר ידנית (חשבונית בת יותר מ-3 שנים — טיפול ידני בלבד)")
            tags.append("manual_only_old")
            state = State.AWAITING_OWNER
        elif ctx.mixed_currency and p.auto_offer_plan and not sensitive:
            reply = (f"{hi}תודה ששיתפתם. נחזור אליכם אישית כדי למצוא יחד פתרון שמתאים לכם.{sig}")
            summary = (f"{name} מבקש/ת הסדר/מתקשה לשלם. לא הוצעה פריסה אוטומטית: החשבוניות "
                       f"הפתוחות במטבעות שונים ({total}).")
            actions.append("להציע הסדר ידנית (חשבוניות במטבעות שונים)")
            tags.append("mixed_currency")
            state = State.AWAITING_OWNER
        elif "reservist" in tags:
            reply = (f"{hi}תודה על השירות! עצרנו את התזכורות לתקופה הקרובה, ונחזור אליכם אישית "
                     f"כשיהיה נוח. אין שום לחץ.{sig}")
            # הפעלה 246: ההשהיה לא משתחררת לבד (רק הבטחה משתחררת, inbox.py) ⇒ הנוסח לא מבטיח "30 יום".
            summary = (f"{name} במילואים. התזכורות הושהו ולא יתחדשו לבד — רק כשתחדש/י אותן. "
                       f"מוצע לבדוק שוב סביב {_he_date(ctx.today + timedelta(days=30))}.")
            actions.append("לחזור אחרי המילואים; לשקול דחייה בלי לחץ")
            actions.append("לחדש תזכורות ידנית כשמתאים (לא מתחדשות לבד)")
            pause_until = ctx.today + timedelta(days=30)
            state = State.AWAITING_OWNER
        elif "insolvency" in tags:
            reply = (f"{hi}תודה שעדכנתם. עצרנו את התזכורות, ונחזור אליכם אישית.{sig}")
            summary = f"🔴 {name} מדווח/ת על הליך חדלות פירעון / פשיטת רגל. התזכורות הושהו; אין להציע הסדר בלי ייעוץ."
            actions.append("לבדוק סטטוס הליך (נאמן/צו) לפני כל פנייה נוספת")
            state = State.AWAITING_OWNER
        elif "sensitive" in tags:
            reply = (f"{hi}מצטערים לשמוע, ומאחלים שיהיה רק טוב. עצרנו את התזכורות לתקופה הקרובה, "
                     f"ונחזור אליכם אישית כשיהיה מתאים.{sig}")
            summary = (f"{name} שיתף/ה במצב רגיש (מחלה/אבל). התזכורות הושהו ולא יתחדשו לבד — "
                       f"רק כשתחדש/י אותן. מוצע לבדוק שוב סביב {_he_date(ctx.today + timedelta(days=30))}.")
            if "deceased" in tags:
                summary = (f"🔴 נמסר על פטירה בהקשר של {name}. התזכורות הושהו; "
                           "אם בעל החשבון נפטר — לא פונים שוב, החוב מול העיזבון.")
            actions.append("לפנות אישית ובעדינות כשיהיה מתאים")
            actions.append("לחדש תזכורות ידנית כשמתאים (לא מתחדשות לבד)")
            pause_until = ctx.today + timedelta(days=30)
            state = State.AWAITING_OWNER
        else:
            reply = (f"{hi}תודה ששיתפתם. נחזור אליכם אישית כדי למצוא יחד פתרון שמתאים לכם.{sig}")
            summary = f"{name} מבקש/ת הסדר/מתקשה לשלם. לא הוצעה פריסה אוטומטית."
            actions.append("להציע הסדר")
            state = State.AWAITING_OWNER
    elif primary == Intent.PROMISE:
        dd, vague = extract_date_ctx(t, ctx)
        if dd is not None and dd >= ctx.today:
            promise_date = dd
            days = (dd - ctx.today).days
            if days <= p.max_defer_days:
                link = f" לתשלום: {ctx.payment_link}" if ctx.payment_link else ""
                reply = (f"תודה{(' ' + ctx.first_name) if ctx.first_name else ''}! רשמנו שהתשלום צפוי עד "
                         f"{_he_date(dd)}, ולא נשלח תזכורות עד אז.{link}{sig}")
                pause_until = dd + timedelta(days=1)
                bump(s=Stop.PAUSE)
                state = State.PROMISED
                summary = f"{name} התחייב/ה לשלם עד {_he_date(dd)}. התזכורות הושהו עד אז."
            else:
                reply = (f"תודה{(' ' + ctx.first_name) if ctx.first_name else ''}. נבדוק את המועד שביקשתם "
                         f"ונחזור אליכם.{sig}")
                bump(Escalation.NORMAL, Stop.PAUSE)
                state = State.AWAITING_OWNER
                summary = (f"{name} מבקש/ת לדחות עד {_he_date(dd)} ({days} ימים) — מעל {p.max_defer_days} "
                           f"הימים שמותר לי לאשר לבד.")
                actions.append("לאשר או להציע מועד אחר")
        else:
            reply = (f"תודה{(' ' + ctx.first_name) if ctx.first_name else ''}! כדי שלא נטריד סתם — "
                     f"עד איזה תאריך בערך יהיה נוח לכם?{sig}")
            pause_until = ctx.today + timedelta(days=3)
            bump(s=Stop.PAUSE)
            state = State.AWAITING_DATE
            summary = f"{name} אמר/ה שישלם/תשלם (בלי תאריך). שאלתי עד מתי; הושהה ל-3 ימים."
            if vague:
                tags.append("vague_date")
    elif primary == Intent.COPY_REQUEST and _s(_RECEIPT, t):
        # critic סבב 102: בקשת *קבלה* רומזת שהלקוח שילם ⇒ לא "נשלח חשבונית"; השהיה עד שבעל העסק בודק
        reply = f"תודה! נבדוק את התשלום אצלנו ונשלח לכם קבלה ברגע שהוא יאומת.{sig}"
        summary = f"{name} ביקש/ה קבלה — ייתכן שכבר שילם/ה. התזכורות הושהו עד שתבדקו."
        actions.append("לבדוק אם התקבל תשלום; אם כן — להנפיק קבלה ולסגור את החשבונית")
        bump(Escalation.NORMAL, Stop.PAUSE)
        tags.append("receipt_request")
    elif primary == Intent.COPY_REQUEST:
        reply = f"בטח. נשלח לכם שוב את {_numbers(ctx) or 'החשבונית'} עם הפירוט בהקדם.{sig}"
        summary = f"{name} מבקש/ת העתק/פירוט של {_numbers(ctx) or 'החשבונית'}."
        actions.append("לשלוח העתק חשבונית מחשבונית ירוקה")
    elif primary == Intent.HOW_TO_PAY:
        if ctx.payment_link:
            amt = f" ({total})" if total else ""
            reply = f"אפשר לשלם{amt} בקישור המאובטח: {ctx.payment_link}\nתודה!{sig}"
            summary = f"{name} שאל/ה איך משלמים — נשלח קישור תשלום."
        else:
            reply = f"נשלח לכם פרטי תשלום בהקדם. תודה!{sig}"
            bump(Escalation.NORMAL)
            summary = f"{name} שאל/ה איך משלמים, ואין קישור תשלום מוגדר."
            actions.append("להגדיר קישור תשלום / לשלוח פרטים")
    elif primary == Intent.CALLBACK:
        reply = f"בשמחה, נחזור אליכם בטלפון בהקדם.{sig}"
        summary = f"{name} מבקש/ת שתתקשרו."
        actions.append("להתקשר ללקוח")
    elif primary == Intent.WHO_IS_THIS:
        reply = f"שלום! ההודעה נשלחה בנוגע לחשבונית שהופקה עבורכם. אם יש שאלה — אפשר להשיב כאן.{sig}"
        summary = f"{name} שאל/ה מי פונה. נשלח זיהוי בלי פרטי חוב."
        if _s(_PHISH, t):
            # מנהל 248: חשש מהונאה — זיהוי העסק בלי קישור, ובעל העסק מאשר אישית שההודעה אמיתית
            reply = (f"שלום! ההודעה נשלחה בנוגע לחשבונית שהופקה עבורכם. אין צורך ללחוץ על שום קישור — "
                     f"אפשר לפנות לעסק ישירות במספר שאתם מכירים, או להשיב כאן ונחזור אליכם.{sig}")
            bump(Escalation.NORMAL)
            tags.append("phishing_concern")
            summary = f"{name} חושש/ת שההודעה מזויפת או לא בטוח/ה לפתוח את הקישור."
            actions.append("לפנות ללקוח מהמספר הרגיל של העסק ולאשר שההודעה אמיתית")
        if _s(_DATA_SOURCE, t):
            # שאלה על מקור המידע/למי נמסר — זכות עיון; עונה בעל העסק, לא אוטומטית
            bump(Escalation.NORMAL)
            tags.append("data_source")
            summary = f"{name} שאל/ה מאיפה יש לכם את הפרטים שלו/ה ולמי נמסרו."
            actions.append("להשיב אישית מאיפה התקבלו הפרטים (לקוח/חשבונית) ושלא הועברו לאחרים")
    elif primary == Intent.ABUSIVE:
        reply = None
        summary = f"{name} השיב/ה בגסות. לא נשלחה תשובה; התזכורות האוטומטיות ממשיכות רק באישורך."
        bump(s=Stop.PAUSE)
        actions.append("להחליט אם להמשיך")
        state = State.AWAITING_OWNER
    elif primary == Intent.THANKS:
        reply = None
        summary = f"{name} אישר/ה קבלה."
    else:
        reply = None
        summary = f"❓ הודעה מ-{name} שלא זיהיתי: \"{_clip(t)}\"."
        actions.append("לקרוא ולהשיב אישית")
        state = State.AWAITING_OWNER

    # סבב 10: העדפת ערוץ ("אל תכתבו במייל, רק בסמס") בלי בקשת הסרה מלאה ⇒ השהיה + כרטיס עם הערוץ.
    # אין במנוע עצירה פר-ערוץ; עדיף להשהות הכול עד שבעל העסק מעדכן, מאשר להמשיך בערוץ שהלקוח דחה.
    _CH = r"(?:מייל|אימייל|מיילים|דוא\"ל|סמס|SMS|מסרונ\w*|הודעה לנייד|נייד|טלפון|וואטסאפ)"
    if stop != Stop.PERMANENT and (
            _s(r"(?:אל|לא)\s+(?:תשלחו|תשלח|תכתבו|תכתוב|לשלוח|לכתוב|תתקשרו|תתקשר|להתקשר)(?:\s+(?:לי|אליי|אלי))?\s+(?:\w+\s+)?(?:ב|ל)?" + _CH, t)
            or _s(r"(?:^|\W)(?:לא|אל)\s+(?:ב|ל)" + _CH, t)
            or _s(r"(?:אל|לא)\s+(?:תתקשרו|תתקשר|להתקשר)", t) and _s(r"(?:תכתבו|במייל|בסמס|בהודעה)", t)
            or _s(r"(?:רק|עדיף(?: לי)? רק)\s+(?:ב|ל|דרך\s+)" + _CH, t) and _s(r"(?:לא|אל)\s", t)
            # critic סבב 91: OPT_OUT שהורד בגלל «רק <ערוץ>» ⇒ לפחות השהיה + כרטיס, לעולם לא «כלום»
            or _hits(RX[Intent.OPT_OUT], t) and _s(r"(?:^|\W)רק\s+(?:ב|ל|דרך\s+)?" + _CH, t)):
        bump(Escalation.NORMAL, Stop.PAUSE)
        tags.append("channel_pref")
        actions.append("לעדכן ערוץ פנייה מועדף לפי בקשת הלקוח, ואז לחדש תזכורות")
    if stop == Stop.PERMANENT:
        pause_until = None
        state = State.OPTED_OUT

    # כשהלקוח כבר ביקש הסרה — עונים רק על בקשה מפורשת, ורק באישור
    if ctx.state == State.OPTED_OUT and primary not in (Intent.HOW_TO_PAY, Intent.COPY_REQUEST,
                                                         Intent.CALLBACK, Intent.DISPUTE,
                                                         Intent.PAID_CLAIM, Intent.DISTRESS):
        reply = None
        if primary not in (Intent.THANKS, Intent.OPT_OUT):
            bump(Escalation.NORMAL)
    if ctx.state == State.OPTED_OUT:
        bump(s=Stop.PERMANENT)
        state = State.OPTED_OUT

    if "reservist" in tags and primary != Intent.CANT_PAY:
        # סט משפט xl-29: הבטחה עיקרית ממי שחזר ממילואים — בעל העסק רואה את ההקשר
        actions.append("הלקוח/ה חזר/ה ממילואים — בלי לחץ; לשקול דחייה אם יבקש/תבקש")
    auto = (ctx.policy.approval_mode == "safe_auto" and reply is not None and primary in SAFE_AUTO
            and esc == Escalation.NONE and not secondary)
    return Decision(
        intent=primary, secondary=secondary, reply=reply, auto_send=auto, escalate=esc, stop=stop,
        pause_until=pause_until if stop == Stop.PAUSE else None, next_state=state, plan=plan,
        promise_date=promise_date, paid_agorot=paid, owner_summary=summary,
        owner_actions=tuple(actions), tags=tuple(dict.fromkeys(tags)))


def _clip(t: str, n: int = 80) -> str:
    return t if len(t) <= n else t[: n - 1] + "…"


def _with_quote(summary: str, text: str) -> str:
    """הפעלה 234: ציטוט אחיד של הודעת הלקוח בכל owner_summary. בעל העסק מאשר/סוגר מהכרטיס — בלי הציטוט
    («שאל/ה איך משלמים», «אישר/ה קבלה») הוא לא יודע מה נכתב בפועל, וסיווג שגוי עובר בלי שיראה.
    כבר מצוטט (מחלוקת/לא זוהה/שפה זרה) ⇒ לא מכפילים. אותם ציטוטים נבנו מהטקסט **המנורמל** (אותיות סופיות
    ⇒ רגילות, «כלומ»; אותיות לטיניות קטנות; ניקוד הוסר) ⇒ מוחלפים בנוסח המקורי של הלקוח."""
    # critic סבב 98: (1) בלי תווי כיוון/בקרה מהלקוח (היפוך ויזואלי של הכרטיס); (2) עד 600 תווים, לא 80 — ב-/ui זה
    # המקום היחיד שבעל העסק רואה את ההודעה, ובקשת הסרה בסוף הודעה ארוכה לא נעלמת ב«…»
    clean = re.sub(r"[\u202a-\u202e\u2066-\u2069\u200e\u200f\u061c\x00-\x08\x0b\x0c\x0e-\x1f\x7f]", "", text or "")
    q = _clip(re.sub(r"\s+", " ", clean).strip(), 600)
    if not q:
        return summary
    if f'"{q}"' in summary:
        return summary
    nq = f'"{_clip(normalize(text))}"'
    if nq in summary:
        return summary.replace(nq, f'"{q}"', 1)
    raw = _clip(re.sub(r"\s+", " ", text or "").strip())
    rq = f'"{raw}"'   # ציטוט קצר/גולמי קודם ⇒ מוחלף בנקי והארוך
    if rq in summary:
        return summary.replace(rq, f'"{q}"', 1)
    return f"{summary} ההודעה: \"{q}\"" if summary else f"ההודעה: \"{q}\""
